BEGIN;
INSERT INTO technologies(slug,name) VALUES ('html','HTML') ON CONFLICT (slug) DO NOTHING;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'basics','Основи HTML','Структура документа, елементи та атрибути' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'text','Текст і базові елементи','Заголовки, абзаци, посилання та цитати' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'lists-tables','Списки і таблиці','Списки, рядки, комірки та заголовки даних' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'forms','Форми','Керування введенням, labels та передаванням даних' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'semantic','Семантичний HTML','Смислова структура сторінки та landmark-елементи' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'media','Медіа та вбудований контент','Зображення, відео, аудіо, iframe та субтитри' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'head','Head і метадані','title, meta, link та ресурси документа' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'accessibility','Accessibility','Доступність, клавіатура, labels та текстові альтернативи' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'seo','Основи SEO','Зрозуміла структура, title, headings та опис сторінки' FROM technologies WHERE slug='html' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
UPDATE questions SET is_active=FALSE WHERE topic_id IN (SELECT topics.id FROM topics JOIN technologies ON technologies.id=topics.technology_id WHERE technologies.slug='html');
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який запис повідомляє браузеру, що документ потрібно обробляти у стандартному режимі HTML?',NULL,'["<!doctype html>","<html>","<head>","<meta charset=\"UTF-8\">"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який запис повідомляє браузеру, що документ потрібно обробляти у стандартному режимі HTML? Правило, яке потрібно запам’ятати: <!doctype html> Варіант «<!doctype html>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<html>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<!doctype html>». Варіант «<head>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<!doctype html>». Варіант «<meta charset="UTF-8">» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<!doctype html>».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент є кореневим елементом HTML-документа?',NULL,'["<html>","<head>","<body>","<main>"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який елемент є кореневим елементом HTML-документа? Правило, яке потрібно запам’ятати: <html> Варіант «<html>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<head>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<html>». Варіант «<body>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<html>». Варіант «<main>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<html>».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент містить видимий вміст HTML-документа?',NULL,'["<body>","<head>","<html>","<title>"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який елемент містить видимий вміст HTML-документа? Правило, яке потрібно запам’ятати: <body> Варіант «<body>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<head>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<body>». Варіант «<html>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<body>». Варіант «<title>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<body>».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут задає унікальний ідентифікатор елемента?',NULL,'["id","class","name","title"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який атрибут задає унікальний ідентифікатор елемента? Правило, яке потрібно запам’ятати: id Варіант «id» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «class» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «id». Варіант «name» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «id». Варіант «title» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «id».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут групує елементи за спільною назвою?',NULL,'["class","id","lang","title"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який атрибут групує елементи за спільною назвою? Правило, яке потрібно запам’ятати: class Варіант «class» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «id» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «class». Варіант «lang» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «class». Варіант «title» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «class».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <!doctype html> правильні?',NULL,'["Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.","Оголошення <!doctype html> записують перед кореневим елементом <html>.","Оголошення <!doctype html> задає кодування документа.","Оголошення <!doctype html> підключає зовнішню таблицю стилів.","Оголошення <!doctype html> визначає мову документа."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про <!doctype html> правильні? Правило, яке потрібно запам’ятати: Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.; Оголошення <!doctype html> записують перед кореневим елементом <html>. Варіант «Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оголошення <!doctype html> записують перед кореневим елементом <html>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оголошення <!doctype html> задає кодування документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.; Оголошення <!doctype html> записують перед кореневим елементом <html>.». Варіант «Оголошення <!doctype html> підключає зовнішню таблицю стилів.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.; Оголошення <!doctype html> записують перед кореневим елементом <html>.». Варіант «Оголошення <!doctype html> визначає мову документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.; Оголошення <!doctype html> записують перед кореневим елементом <html>.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи безпосередньо розділяють HTML-документ на службову та видиму частини?',NULL,'["<head>","<body>","<main>","<title>","<header>"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два елементи безпосередньо розділяють HTML-документ на службову та видиму частини? Правило, яке потрібно запам’ятати: <head>; <body> Варіант «<head>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<body>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<main>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<head>; <body>». Варіант «<title>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<head>; <body>». Варіант «<header>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<head>; <body>».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про атрибут lang правильні?',NULL,'["Атрибут lang указує мову текстового вмісту елемента.","Атрибут lang на <html> задає основну мову документа.","Атрибут lang задає кодування символів документа.","Атрибут lang створює унікальний ідентифікатор.","Атрибут lang визначає напрямок письма."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про атрибут lang правильні? Правило, яке потрібно запам’ятати: Атрибут lang указує мову текстового вмісту елемента.; Атрибут lang на <html> задає основну мову документа. Варіант «Атрибут lang указує мову текстового вмісту елемента.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Атрибут lang на <html> задає основну мову документа.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Атрибут lang задає кодування символів документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут lang указує мову текстового вмісту елемента.; Атрибут lang на <html> задає основну мову документа.». Варіант «Атрибут lang створює унікальний ідентифікатор.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут lang указує мову текстового вмісту елемента.; Атрибут lang на <html> задає основну мову документа.». Варіант «Атрибут lang визначає напрямок письма.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут lang указує мову текстового вмісту елемента.; Атрибут lang на <html> задає основну мову документа.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два варіанти HTML-розмітки мають правильну вкладеність?',NULL,'["<p><strong>Текст</strong></p>","<ul><li>Пункт</li></ul>","<p><strong>Текст</p></strong>","<ul>Пункт<li></li></ul>","<head><body>Вміст</body></head>"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два варіанти HTML-розмітки мають правильну вкладеність? Правило, яке потрібно запам’ятати: <p><strong>Текст</strong></p>; <ul><li>Пункт</li></ul> Варіант «<p><strong>Текст</strong></p>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<ul><li>Пункт</li></ul>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<p><strong>Текст</p></strong>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p><strong>Текст</strong></p>; <ul><li>Пункт</li></ul>». Варіант «<ul>Пункт<li></li></ul>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p><strong>Текст</strong></p>; <ul><li>Пункт</li></ul>». Варіант «<head><body>Вміст</body></head>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p><strong>Текст</strong></p>; <ul><li>Пункт</li></ul>».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про void-елементи правильні?',NULL,'["Void-елемент <img> не має окремого закривального тегу.","Void-елемент <br> вставляє перенесення рядка.","Елемент <img> потрібно завершувати тегом </img>.","Елемент <br> може містити текстовий вміст.","Void-елементи потрібно записувати лише всередині <head>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про void-елементи правильні? Правило, яке потрібно запам’ятати: Void-елемент <img> не має окремого закривального тегу.; Void-елемент <br> вставляє перенесення рядка. Варіант «Void-елемент <img> не має окремого закривального тегу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Void-елемент <br> вставляє перенесення рядка.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Елемент <img> потрібно завершувати тегом </img>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Void-елемент <img> не має окремого закривального тегу.; Void-елемент <br> вставляє перенесення рядка.». Варіант «Елемент <br> може містити текстовий вміст.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Void-елемент <img> не має окремого закривального тегу.; Void-елемент <br> вставляє перенесення рядка.». Варіант «Void-елементи потрібно записувати лише всередині <head>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Void-елемент <img> не має окремого закривального тегу.; Void-елемент <br> вставляє перенесення рядка.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про <!doctype html> правильні?',NULL,'["Оголошення <!doctype html> розміщують перед елементом <html>.","Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.","Оголошення <!doctype html> задає кодування UTF-8.","Оголошення <!doctype html> визначає мову документа.","Оголошення <!doctype html> підключає основну таблицю стилів.","Оголошення <!doctype html> створює елемент <body>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про <!doctype html> правильні? Правило, яке потрібно запам’ятати: Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення. Варіант «Оголошення <!doctype html> розміщують перед елементом <html>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оголошення <!doctype html> задає кодування UTF-8.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.». Варіант «Оголошення <!doctype html> визначає мову документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.». Варіант «Оголошення <!doctype html> підключає основну таблицю стилів.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.». Варіант «Оголошення <!doctype html> створює елемент <body>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елемент <html> правильні?',NULL,'["Елемент <html> є кореневим елементом HTML-документа.","Елементи <head> і <body> розміщують усередині <html>.","Елемент <html> містить лише видимий вміст сторінки.","Елемент <html> використовують замість <!doctype html>.","Елемент <html> може бути дочірнім елементом <body>.","Елемент <html> задає кодування документа без <meta>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про елемент <html> правильні? Правило, яке потрібно запам’ятати: Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>. Варіант «Елемент <html> є кореневим елементом HTML-документа.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Елементи <head> і <body> розміщують усередині <html>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Елемент <html> містить лише видимий вміст сторінки.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>.». Варіант «Елемент <html> використовують замість <!doctype html>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>.». Варіант «Елемент <html> може бути дочірнім елементом <body>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>.». Варіант «Елемент <html> задає кодування документа без <meta>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елемент <body> правильні?',NULL,'["Елемент <body> містить видимий вміст HTML-документа.","HTML-документ має не більше одного елемента <body>.","Елемент <body> призначений лише для метаданих документа.","Елемент <body> потрібно розміщувати всередині <head>.","Елемент <body> замінює кореневий елемент <html>.","Елемент <body> не може містити елементи <p>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про елемент <body> правильні? Правило, яке потрібно запам’ятати: Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>. Варіант «Елемент <body> містить видимий вміст HTML-документа.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «HTML-документ має не більше одного елемента <body>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Елемент <body> призначений лише для метаданих документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>.». Варіант «Елемент <body> потрібно розміщувати всередині <head>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>.». Варіант «Елемент <body> замінює кореневий елемент <html>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>.». Варіант «Елемент <body> не може містити елементи <p>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про атрибут id правильні?',NULL,'["Значення id має ідентифікувати один елемент у документі.","Значення id можна використовувати як ціль фрагментного URL.","Атрибут id групує довільну кількість елементів під одним значенням.","Атрибут id задає мову текстового вмісту.","Значення id потрібно дублювати для пов’язаних елементів.","Атрибут id можна використовувати лише з елементом <div>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про атрибут id правильні? Правило, яке потрібно запам’ятати: Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL. Варіант «Значення id має ідентифікувати один елемент у документі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Значення id можна використовувати як ціль фрагментного URL.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Атрибут id групує довільну кількість елементів під одним значенням.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL.». Варіант «Атрибут id задає мову текстового вмісту.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL.». Варіант «Значення id потрібно дублювати для пов’язаних елементів.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL.». Варіант «Атрибут id можна використовувати лише з елементом <div>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про атрибут class правильні?',NULL,'["Атрибут class групує елементи за спільними назвами класів.","Один елемент може мати кілька назв класів.","Значення class має бути унікальним у всьому документі.","Атрибут class задає адресу переходу для <a>.","Атрибут class визначає основну мову документа.","Атрибут class можна використовувати лише з елементом <div>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про атрибут class правильні? Правило, яке потрібно запам’ятати: Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів. Варіант «Атрибут class групує елементи за спільними назвами класів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Один елемент може мати кілька назв класів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Значення class має бути унікальним у всьому документі.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів.». Варіант «Атрибут class задає адресу переходу для <a>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів.». Варіант «Атрибут class визначає основну мову документа.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів.». Варіант «Атрибут class можна використовувати лише з елементом <div>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів.».' FROM topics WHERE slug='basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає окремий абзац тексту?',NULL,'["<p>","<h1>","<span>","<blockquote>"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який елемент позначає окремий абзац тексту? Правило, яке потрібно запам’ятати: <p> Варіант «<p>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<h1>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p>». Варіант «<span>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p>». Варіант «<blockquote>» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «<p>».' FROM topics WHERE slug='text' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
