INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <video> правильні?',NULL,'["Атрибут controls додає користувацькі елементи керування відео.","Елемент <source> задає альтернативний відеоресурс.","Атрибут controls задає адресу відеофайлу.","Елемент <source> підключає файл субтитрів.","Елемент <video> може містити лише один <source>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про <video> правильні? Правило, яке потрібно запам’ятати: Атрибут controls додає користувацькі елементи керування відео.; Елемент <source> задає альтернативний відеоресурс. Варіант «Атрибут controls додає користувацькі елементи керування відео.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Елемент <source> задає альтернативний відеоресурс.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Атрибут controls задає адресу відеофайлу.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут controls додає користувацькі елементи керування відео.; Елемент <source> задає альтернативний відеоресурс.». Варіант «Елемент <source> підключає файл субтитрів.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут controls додає користувацькі елементи керування відео.; Елемент <source> задає альтернативний відеоресурс.». Варіант «Елемент <video> може містити лише один <source>.» неправильний: він суперечить перевірюваному правилу HTML. Для цієї умови правильні положення: «Атрибут controls додає користувацькі елементи керування відео.; Елемент <source> задає альтернативний відеоресурс.».' FROM topics WHERE slug='media' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
