INSERT INTO topics(technology_id,slug,name,description) SELECT id,'display','Display','Типи генерованих блоків, участь у потоці та приховування елементів.' FROM technologies WHERE slug='css' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
