UPDATE questions SET is_active=FALSE WHERE topic_id IN (SELECT topics.id FROM topics JOIN technologies ON technologies.id=topics.technology_id WHERE technologies.slug='css');
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка частина CSS-оголошення вказує, що саме потрібно стилізувати?',NULL,'["Властивість","Значення","Селектор","Коментар"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка частина CSS-оголошення вказує, що саме потрібно стилізувати? Правило, яке потрібно запам’ятати: Властивість Варіант «Властивість» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Значення» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Властивість». Варіант «Селектор» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Властивість». Варіант «Коментар» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Властивість».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який HTML-елемент підключає зовнішній CSS-файл?',NULL,'["<style>","<link>","<script>","<meta>"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Який HTML-елемент підключає зовнішній CSS-файл? Правило, яке потрібно запам’ятати: <link> Варіант «<style>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<link>». Варіант «<link>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<script>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<link>». Варіант «<meta>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<link>».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','У якому HTML-елементі розміщують внутрішні CSS-правила?',NULL,'["<link>","<script>","<style>","<head>"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: У якому HTML-елементі розміщують внутрішні CSS-правила? Правило, яке потрібно запам’ятати: <style> Варіант «<link>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<style>». Варіант «<script>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<style>». Варіант «<style>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «<head>» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «<style>».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який запис правильно оформлює коментар у CSS?',NULL,'["// коментар","<!-- коментар -->","# коментар","/* коментар */"]'::jsonb,'[3]'::jsonb,'Питання перевіряє: Який запис правильно оформлює коментар у CSS? Правило, яке потрібно запам’ятати: /* коментар */ Варіант «// коментар» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «/* коментар */». Варіант «<!-- коментар -->» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «/* коментар */». Варіант «# коментар» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «/* коментар */». Варіант «/* коментар */» правильний: це один із результатів або правил, які безпосередньо виконує умову питання.' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який символ відокремлює CSS-властивість від її значення?',NULL,'["Двокрапка","Крапка з комою","Кома","Знак рівності"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який символ відокремлює CSS-властивість від її значення? Правило, яке потрібно запам’ятати: Двокрапка Варіант «Двокрапка» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Крапка з комою» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка». Варіант «Кома» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка». Варіант «Знак рівності» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують правило p { color: red; }?',NULL,'["Селектор p вибирає елементи <p>.","Оголошення задає червоний колір тексту.","Властивість color змінює колір фону.","Значення red визначає товщину шрифту.","Фігурні дужки створюють HTML-елемент."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують правило p { color: red; }? Правило, яке потрібно запам’ятати: Селектор p вибирає елементи <p>.; Оголошення задає червоний колір тексту. Варіант «Селектор p вибирає елементи <p>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оголошення задає червоний колір тексту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Властивість color змінює колір фону.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор p вибирає елементи <p>.; Оголошення задає червоний колір тексту.». Варіант «Значення red визначає товщину шрифту.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор p вибирає елементи <p>.; Оголошення задає червоний колір тексту.». Варіант «Фігурні дужки створюють HTML-елемент.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор p вибирає елементи <p>.; Оголошення задає червоний колір тексту.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два способи правильно додають CSS до HTML-документа?',NULL,'["Підключити CSS-файл через <link>.","Розмістити правила всередині <style>.","Записати правила в атрибуті ''src'' елемента <script>.","Додати CSS-файл через <meta>.","Розмістити правила всередині <title>."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два способи правильно додають CSS до HTML-документа? Правило, яке потрібно запам’ятати: Підключити CSS-файл через <link>.; Розмістити правила всередині <style>. Варіант «Підключити CSS-файл через <link>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Розмістити правила всередині <style>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Записати правила в атрибуті ''src'' елемента <script>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Підключити CSS-файл через <link>.; Розмістити правила всередині <style>.». Варіант «Додати CSS-файл через <meta>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Підключити CSS-файл через <link>.; Розмістити правила всередині <style>.». Варіант «Розмістити правила всередині <title>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Підключити CSS-файл через <link>.; Розмістити правила всередині <style>.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про CSS-оголошення правильні?',NULL,'["Двокрапка відокремлює властивість від значення.","Крапка з комою відокремлює сусідні оголошення.","Кома завершує кожне оголошення.","Знак рівності поєднує властивість зі значенням.","Круглі дужки містять блок оголошень."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про CSS-оголошення правильні? Правило, яке потрібно запам’ятати: Двокрапка відокремлює властивість від значення.; Крапка з комою відокремлює сусідні оголошення. Варіант «Двокрапка відокремлює властивість від значення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Крапка з комою відокремлює сусідні оголошення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кома завершує кожне оголошення.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка відокремлює властивість від значення.; Крапка з комою відокремлює сусідні оголошення.». Варіант «Знак рівності поєднує властивість зі значенням.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка відокремлює властивість від значення.; Крапка з комою відокремлює сусідні оголошення.». Варіант «Круглі дужки містять блок оголошень.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Двокрапка відокремлює властивість від значення.; Крапка з комою відокремлює сусідні оголошення.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження описують обробку некоректного CSS?',NULL,'["Браузер ігнорує оголошення з невідомою властивістю.","Інші коректні оголошення правила можуть бути застосовані.","Одна невідома властивість припиняє обробку всього CSS-файлу.","Браузер перетворює невідому властивість на найближчу відому.","Некоректне оголошення видаляє відповідний HTML-елемент."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження описують обробку некоректного CSS? Правило, яке потрібно запам’ятати: Браузер ігнорує оголошення з невідомою властивістю.; Інші коректні оголошення правила можуть бути застосовані. Варіант «Браузер ігнорує оголошення з невідомою властивістю.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Інші коректні оголошення правила можуть бути застосовані.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Одна невідома властивість припиняє обробку всього CSS-файлу.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Браузер ігнорує оголошення з невідомою властивістю.; Інші коректні оголошення правила можуть бути застосовані.». Варіант «Браузер перетворює невідому властивість на найближчу відому.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Браузер ігнорує оголошення з невідомою властивістю.; Інші коректні оголошення правила можуть бути застосовані.». Варіант «Некоректне оголошення видаляє відповідний HTML-елемент.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Браузер ігнорує оголошення з невідомою властивістю.; Інші коректні оголошення правила можуть бути застосовані.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два записи потрібні для підключення файлу styles.css?',NULL,'["В елементі <link> потрібно вказати ''rel''=''stylesheet''.","В атрибуті ''href'' потрібно вказати шлях до styles.css.","В атрибуті ''method'' потрібно вказати CSS.","В елементі <style> потрібно вказати ''src''=''styles.css''.","В атрибуті ''type'' елемента <meta> потрібно вказати stylesheet."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два записи потрібні для підключення файлу styles.css? Правило, яке потрібно запам’ятати: В елементі <link> потрібно вказати ''rel''=''stylesheet''.; В атрибуті ''href'' потрібно вказати шлях до styles.css. Варіант «В елементі <link> потрібно вказати ''rel''=''stylesheet''.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «В атрибуті ''href'' потрібно вказати шлях до styles.css.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «В атрибуті ''method'' потрібно вказати CSS.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «В елементі <link> потрібно вказати ''rel''=''stylesheet''.; В атрибуті ''href'' потрібно вказати шлях до styles.css.». Варіант «В елементі <style> потрібно вказати ''src''=''styles.css''.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «В елементі <link> потрібно вказати ''rel''=''stylesheet''.; В атрибуті ''href'' потрібно вказати шлях до styles.css.». Варіант «В атрибуті ''type'' елемента <meta> потрібно вказати stylesheet.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «В елементі <link> потрібно вказати ''rel''=''stylesheet''.; В атрибуті ''href'' потрібно вказати шлях до styles.css.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про зовнішню таблицю стилів правильні?',NULL,'["CSS-файл містить правила без елемента <style>.","HTML-документ може підключити файл через <link>.","CSS-файл має містити всі правила всередині елемента <style>.","HTML-документ підключає CSS-файл через ''src'' елемента <link>.","Зовнішній CSS-файл потрібно зберігати в одній папці з HTML-файлом.","Один HTML-документ може підключити лише один зовнішній CSS-файл."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про зовнішню таблицю стилів правильні? Правило, яке потрібно запам’ятати: CSS-файл містить правила без елемента <style>.; HTML-документ може підключити файл через <link>. Варіант «CSS-файл містить правила без елемента <style>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «HTML-документ може підключити файл через <link>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «CSS-файл має містити всі правила всередині елемента <style>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «CSS-файл містить правила без елемента <style>.; HTML-документ може підключити файл через <link>.». Варіант «HTML-документ підключає CSS-файл через ''src'' елемента <link>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «CSS-файл містить правила без елемента <style>.; HTML-документ може підключити файл через <link>.». Варіант «Зовнішній CSS-файл потрібно зберігати в одній папці з HTML-файлом.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «CSS-файл містить правила без елемента <style>.; HTML-документ може підключити файл через <link>.». Варіант «Один HTML-документ може підключити лише один зовнішній CSS-файл.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «CSS-файл містить правила без елемента <style>.; HTML-документ може підключити файл через <link>.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про блок CSS-оголошень правильні?',NULL,'["Блок оголошень розміщують у фігурних дужках.","Кожне оголошення складається з властивості та значення.","Селектор потрібно записувати після закривної дужки.","Властивості від значень відокремлюють комою.","Один блок може стилізувати лише один HTML-елемент.","Коментар CSS починається символами //."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про блок CSS-оголошень правильні? Правило, яке потрібно запам’ятати: Блок оголошень розміщують у фігурних дужках.; Кожне оголошення складається з властивості та значення. Варіант «Блок оголошень розміщують у фігурних дужках.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кожне оголошення складається з властивості та значення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Селектор потрібно записувати після закривної дужки.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок оголошень розміщують у фігурних дужках.; Кожне оголошення складається з властивості та значення.». Варіант «Властивості від значень відокремлюють комою.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок оголошень розміщують у фігурних дужках.; Кожне оголошення складається з властивості та значення.». Варіант «Один блок може стилізувати лише один HTML-елемент.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок оголошень розміщують у фігурних дужках.; Кожне оголошення складається з властивості та значення.». Варіант «Коментар CSS починається символами //.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок оголошень розміщують у фігурних дужках.; Кожне оголошення складається з властивості та значення.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два наслідки матиме невідоме CSS-оголошення в коректному правилі?',NULL,'["Невідоме оголошення не вплине на оформлення.","Коректні оголошення цього правила залишаться придатними до застосування.","Браузер відкине весь блок оголошень цього правила.","Браузер застосує невідому властивість як найближчу відому.","Усі наступні правила таблиці стилів буде відкинуто.","Попереднє коректне оголошення тієї самої властивості стане недійсним."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два наслідки матиме невідоме CSS-оголошення в коректному правилі? Правило, яке потрібно запам’ятати: Невідоме оголошення не вплине на оформлення.; Коректні оголошення цього правила залишаться придатними до застосування. Варіант «Невідоме оголошення не вплине на оформлення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коректні оголошення цього правила залишаться придатними до застосування.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Браузер відкине весь блок оголошень цього правила.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Невідоме оголошення не вплине на оформлення.; Коректні оголошення цього правила залишаться придатними до застосування.». Варіант «Браузер застосує невідому властивість як найближчу відому.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Невідоме оголошення не вплине на оформлення.; Коректні оголошення цього правила залишаться придатними до застосування.». Варіант «Усі наступні правила таблиці стилів буде відкинуто.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Невідоме оголошення не вплине на оформлення.; Коректні оголошення цього правила залишаться придатними до застосування.». Варіант «Попереднє коректне оголошення тієї самої властивості стане недійсним.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Невідоме оголошення не вплине на оформлення.; Коректні оголошення цього правила залишаться придатними до застосування.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про порядок однакових CSS-оголошень правильні?',NULL,'["За однакової ваги пізніше оголошення має перевагу.","Каскад визначає, яке значення властивості буде використано.","Перше оголошення має перевагу незалежно від селектора.","Порядок правил впливає лише на HTML-атрибути.","Повторення властивості робить обидва оголошення недійсними.","Браузер обчислює середнє значення двох оголошень."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про порядок однакових CSS-оголошень правильні? Правило, яке потрібно запам’ятати: За однакової ваги пізніше оголошення має перевагу.; Каскад визначає, яке значення властивості буде використано. Варіант «За однакової ваги пізніше оголошення має перевагу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Каскад визначає, яке значення властивості буде використано.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Перше оголошення має перевагу незалежно від селектора.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «За однакової ваги пізніше оголошення має перевагу.; Каскад визначає, яке значення властивості буде використано.». Варіант «Порядок правил впливає лише на HTML-атрибути.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «За однакової ваги пізніше оголошення має перевагу.; Каскад визначає, яке значення властивості буде використано.». Варіант «Повторення властивості робить обидва оголошення недійсними.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «За однакової ваги пізніше оголошення має перевагу.; Каскад визначає, яке значення властивості буде використано.». Варіант «Браузер обчислює середнє значення двох оголошень.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «За однакової ваги пізніше оголошення має перевагу.; Каскад визначає, яке значення властивості буде використано.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про CSS-коментарі правильні?',NULL,'["Коментар можна розмістити між CSS-оголошеннями.","Вміст між /* та */ не застосовується як CSS-код.","Коментар // підтримується як стандартний багаторядковий синтаксис CSS.","Коментар змінює специфічність сусіднього селектора.","Коментар потрібно вкладати в лапки.","Коментар відображається як текст сторінки."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про CSS-коментарі правильні? Правило, яке потрібно запам’ятати: Коментар можна розмістити між CSS-оголошеннями.; Вміст між /* та */ не застосовується як CSS-код. Варіант «Коментар можна розмістити між CSS-оголошеннями.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Вміст між /* та */ не застосовується як CSS-код.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коментар // підтримується як стандартний багаторядковий синтаксис CSS.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Коментар можна розмістити між CSS-оголошеннями.; Вміст між /* та */ не застосовується як CSS-код.». Варіант «Коментар змінює специфічність сусіднього селектора.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Коментар можна розмістити між CSS-оголошеннями.; Вміст між /* та */ не застосовується як CSS-код.». Варіант «Коментар потрібно вкладати в лапки.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Коментар можна розмістити між CSS-оголошеннями.; Вміст між /* та */ не застосовується як CSS-код.». Варіант «Коментар відображається як текст сторінки.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Коментар можна розмістити між CSS-оголошеннями.; Вміст між /* та */ не застосовується як CSS-код.».' FROM topics WHERE slug='css-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який селектор вибирає всі елементи з класом card?',NULL,'["#card",".card","card","[card]"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Який селектор вибирає всі елементи з класом card? Правило, яке потрібно запам’ятати: .card Варіант «#card» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «.card». Варіант «.card» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «card» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «.card». Варіант «[card]» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «.card».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який селектор вибирає елемент з ідентифікатором menu?',NULL,'[".menu","menu","#menu","[menu]"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Який селектор вибирає елемент з ідентифікатором menu? Правило, яке потрібно запам’ятати: #menu Варіант «.menu» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#menu». Варіант «menu» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#menu». Варіант «#menu» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «[menu]» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#menu».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який комбінатор вибирає лише безпосередніх дочірніх елементів?',NULL,'["Пробіл","+","~",">"]'::jsonb,'[3]'::jsonb,'Питання перевіряє: Який комбінатор вибирає лише безпосередніх дочірніх елементів? Правило, яке потрібно запам’ятати: > Варіант «Пробіл» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «>». Варіант «+» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «>». Варіант «~» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «>». Варіант «>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання.' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який селектор вибирає елементи з атрибутом ''disabled''?',NULL,'[".disabled","#disabled","[disabled]",":disabled-value"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Який селектор вибирає елементи з атрибутом ''disabled''? Правило, яке потрібно запам’ятати: [disabled] Варіант «.disabled» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[disabled]». Варіант «#disabled» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[disabled]». Варіант «[disabled]» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «:disabled-value» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[disabled]».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який псевдоклас застосовують під час наведення вказівника?',NULL,'[":focus",":hover",":checked",":first-child"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Який псевдоклас застосовують під час наведення вказівника? Правило, яке потрібно запам’ятати: :hover Варіант «:focus» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «:hover». Варіант «:hover» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «:checked» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «:hover». Варіант «:first-child» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «:hover».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про селектор .card.active правильні?',NULL,'["Селектор збігається з елементом, який має обидва класи card та active.","Кожна крапка в записі позначає окремий селектор класу.","Селектор вибирає елемент active усередині елемента card.","Селектор збігається з елементом, який має лише клас card.","Назва card у цьому записі є селектором ідентифікатора."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про селектор .card.active правильні? Правило, яке потрібно запам’ятати: Селектор збігається з елементом, який має обидва класи card та active.; Кожна крапка в записі позначає окремий селектор класу. Варіант «Селектор збігається з елементом, який має обидва класи card та active.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кожна крапка в записі позначає окремий селектор класу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Селектор вибирає елемент active усередині елемента card.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор збігається з елементом, який має обидва класи card та active.; Кожна крапка в записі позначає окремий селектор класу.». Варіант «Селектор збігається з елементом, який має лише клас card.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор збігається з елементом, який має обидва класи card та active.; Кожна крапка в записі позначає окремий селектор класу.». Варіант «Назва card у цьому записі є селектором ідентифікатора.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор збігається з елементом, який має обидва класи card та active.; Кожна крапка в записі позначає окремий селектор класу.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про селектор .menu a правильні?',NULL,'["Він вибирає елементи <a> всередині елемента з класом menu.","Посилання може бути вкладене в menu не безпосередньо.","Він вибирає елемент, який має одночасно класи menu та a.","Він вибирає тільки безпосередні дочірні посилання.","Він вибирає елемент <menu> з атрибутом ''a''."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про селектор .menu a правильні? Правило, яке потрібно запам’ятати: Він вибирає елементи <a> всередині елемента з класом menu.; Посилання може бути вкладене в menu не безпосередньо. Варіант «Він вибирає елементи <a> всередині елемента з класом menu.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Посилання може бути вкладене в menu не безпосередньо.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Він вибирає елемент, який має одночасно класи menu та a.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Він вибирає елементи <a> всередині елемента з класом menu.; Посилання може бути вкладене в menu не безпосередньо.». Варіант «Він вибирає тільки безпосередні дочірні посилання.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Він вибирає елементи <a> всередині елемента з класом menu.; Посилання може бути вкладене в menu не безпосередньо.». Варіант «Він вибирає елемент <menu> з атрибутом ''a''.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Він вибирає елементи <a> всередині елемента з класом menu.; Посилання може бути вкладене в menu не безпосередньо.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про список селекторів h1, h2 правильні?',NULL,'["Правило застосовується до елементів <h1>.","Правило застосовується до елементів <h2>.","Правило застосовується тільки до <h2> всередині <h1>.","Кома позначає безпосередню вкладеність.","Обидва селектори мають збігтися з одним елементом."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про список селекторів h1, h2 правильні? Правило, яке потрібно запам’ятати: Правило застосовується до елементів <h1>.; Правило застосовується до елементів <h2>. Варіант «Правило застосовується до елементів <h1>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Правило застосовується до елементів <h2>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Правило застосовується тільки до <h2> всередині <h1>.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Правило застосовується до елементів <h1>.; Правило застосовується до елементів <h2>.». Варіант «Кома позначає безпосередню вкладеність.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Правило застосовується до елементів <h1>.; Правило застосовується до елементів <h2>.». Варіант «Обидва селектори мають збігтися з одним елементом.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Правило застосовується до елементів <h1>.; Правило застосовується до елементів <h2>.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два селектори виберуть другий пункт списку, якщо всі діти <ul> є елементами <li>?',NULL,'["li:nth-child(2)","li:nth-of-type(2)","li:first-child","li:nth-child(odd)","li:last-of-type:first-child"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два селектори виберуть другий пункт списку, якщо всі діти <ul> є елементами <li>? Правило, яке потрібно запам’ятати: li:nth-child(2); li:nth-of-type(2) Варіант «li:nth-child(2)» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «li:nth-of-type(2)» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «li:first-child» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «li:nth-child(2); li:nth-of-type(2)». Варіант «li:nth-child(odd)» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «li:nth-child(2); li:nth-of-type(2)». Варіант «li:last-of-type:first-child» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «li:nth-child(2); li:nth-of-type(2)».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два селектори перевіряють значення атрибута ''type''?',NULL,'["[type=''email'']","input[type=''email'']",".type-email","#type=email",":type(''email'')"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два селектори перевіряють значення атрибута ''type''? Правило, яке потрібно запам’ятати: [type=''email'']; input[type=''email''] Варіант «[type=''email'']» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «input[type=''email'']» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «.type-email» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[type=''email'']; input[type=''email'']». Варіант «#type=email» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[type=''email'']; input[type=''email'']». Варіант «:type(''email'')» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «[type=''email'']; input[type=''email'']».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який текст стане червоним після застосування цих правил?','<p class="note active">A</p>
<p class="note">B</p>

.note.active {
  color: red;
}','["Лише текст A.","Лише текст B.","Обидва тексти.","Жоден текст."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який текст стане червоним після застосування цих правил? Правило, яке потрібно запам’ятати: Лише текст A. Варіант «Лише текст A.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише текст B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише текст A.». Варіант «Обидва тексти.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише текст A.». Варіант «Жоден текст.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише текст A.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який елемент отримає рамку?','<div class="box">
  <span>A</span>
  <p><span>B</span></p>
</div>

.box > span {
  border: 1px solid;
}','["Лише безпосередній <span> із текстом A.","Лише вкладений <span> із текстом B.","Обидва елементи <span>.","Жоден елемент <span>."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який елемент отримає рамку? Правило, яке потрібно запам’ятати: Лише безпосередній <span> із текстом A. Варіант «Лише безпосередній <span> із текстом A.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише вкладений <span> із текстом B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише безпосередній <span> із текстом A.». Варіант «Обидва елементи <span>.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише безпосередній <span> із текстом A.». Варіант «Жоден елемент <span>.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише безпосередній <span> із текстом A.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які посилання отримають підкреслення?','<a href="guide.pdf">Посібник</a>
<a href="cover.png">Обкладинка</a>

a[href$=".pdf"] {
  text-decoration: underline;
}','["Лише посилання на PDF-файл.","Лише посилання на PNG-файл.","Обидва посилання.","Жодне посилання."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Які посилання отримають підкреслення? Правило, яке потрібно запам’ятати: Лише посилання на PDF-файл. Варіант «Лише посилання на PDF-файл.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише посилання на PNG-файл.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише посилання на PDF-файл.». Варіант «Обидва посилання.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише посилання на PDF-файл.». Варіант «Жодне посилання.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише посилання на PDF-файл.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який пункт списку стане жирним?','<ul>
  <li>Один</li>
  <li>Два</li>
</ul>

li:first-child {
  font-weight: 700;
}','["Пункт Один.","Пункт Два.","Обидва пункти.","Жоден пункт."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який пункт списку стане жирним? Правило, яке потрібно запам’ятати: Пункт Один. Варіант «Пункт Один.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Пункт Два.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Пункт Один.». Варіант «Обидва пункти.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Пункт Один.». Варіант «Жоден пункт.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Пункт Один.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які кнопки матимуть сірий фон?','<button>Зберегти</button>
<button disabled>Видалити</button>

button:not([disabled]) {
  background: gray;
}','["Лише кнопка Зберегти.","Лише вимкнена кнопка Видалити.","Обидві кнопки.","Жодна кнопка."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Які кнопки матимуть сірий фон? Правило, яке потрібно запам’ятати: Лише кнопка Зберегти. Варіант «Лише кнопка Зберегти.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише вимкнена кнопка Видалити.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише кнопка Зберегти.». Варіант «Обидві кнопки.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише кнопка Зберегти.». Варіант «Жодна кнопка.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише кнопка Зберегти.».' FROM topics WHERE slug='selectors' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка властивість зазвичай успадковується дочірніми елементами?',NULL,'["margin","border","color","width"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Яка властивість зазвичай успадковується дочірніми елементами? Правило, яке потрібно запам’ятати: color Варіант «margin» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color». Варіант «border» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color». Варіант «color» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «width» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який селектор має найвищу специфічність?',NULL,'["p",".note","#message","*"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Який селектор має найвищу специфічність? Правило, яке потрібно запам’ятати: #message Варіант «p» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#message». Варіант «.note» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#message». Варіант «#message» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «*» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «#message».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке CSS-значення примусово бере обчислене значення від батьківського елемента?',NULL,'["initial","inherit","unset","revert"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яке CSS-значення примусово бере обчислене значення від батьківського елемента? Правило, яке потрібно запам’ятати: inherit Варіант «initial» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «inherit». Варіант «inherit» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «unset» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «inherit». Варіант «revert» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «inherit».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що визначає каскад, коли кілька оголошень задають одну властивість?',NULL,'["Яке оголошення матиме перевагу","Чи потрібно об''єднати значення оголошень","Чи потрібно відкинути всі конфліктні оголошення","Чи потрібно успадкувати значення без порівняння"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що визначає каскад, коли кілька оголошень задають одну властивість? Правило, яке потрібно запам’ятати: Яке оголошення матиме перевагу Варіант «Яке оголошення матиме перевагу» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Чи потрібно об''єднати значення оголошень» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Яке оголошення матиме перевагу». Варіант «Чи потрібно відкинути всі конфліктні оголошення» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Яке оголошення матиме перевагу». Варіант «Чи потрібно успадкувати значення без порівняння» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Яке оголошення матиме перевагу».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка частина селектора #app .title має найбільшу вагу?',NULL,'["Універсальний селектор","Селектор типу","Селектор класу","Селектор ідентифікатора"]'::jsonb,'[3]'::jsonb,'Питання перевіряє: Яка частина селектора #app .title має найбільшу вагу? Правило, яке потрібно запам’ятати: Селектор ідентифікатора Варіант «Універсальний селектор» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора». Варіант «Селектор типу» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора». Варіант «Селектор класу» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора». Варіант «Селектор ідентифікатора» правильний: це один із результатів або правил, які безпосередньо виконує умову питання.' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про специфічність правильні?',NULL,'["Селектор ідентифікатора важить більше за селектор класу.","За однакової специфічності перевагу має пізніше оголошення.","Селектор типу важить більше за ідентифікатор.","Кількість CSS-файлів додається до специфічності.","Успадковане значення має перевагу над прямим оголошенням."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про специфічність правильні? Правило, яке потрібно запам’ятати: Селектор ідентифікатора важить більше за селектор класу.; За однакової специфічності перевагу має пізніше оголошення. Варіант «Селектор ідентифікатора важить більше за селектор класу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «За однакової специфічності перевагу має пізніше оголошення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Селектор типу важить більше за ідентифікатор.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора важить більше за селектор класу.; За однакової специфічності перевагу має пізніше оголошення.». Варіант «Кількість CSS-файлів додається до специфічності.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора важить більше за селектор класу.; За однакової специфічності перевагу має пізніше оголошення.». Варіант «Успадковане значення має перевагу над прямим оголошенням.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Селектор ідентифікатора важить більше за селектор класу.; За однакової специфічності перевагу має пізніше оголошення.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві властивості зазвичай успадковуються?',NULL,'["color","font-family","margin","padding","border-width"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві властивості зазвичай успадковуються? Правило, яке потрібно запам’ятати: color; font-family Варіант «color» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «font-family» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «margin» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color; font-family». Варіант «padding» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color; font-family». Варіант «border-width» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «color; font-family».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про !important правильні?',NULL,'["Позначене оголошення бере участь у каскаді з підвищеною важливістю.","Між двома важливими оголошеннями враховується специфічність.","Позначення скасовує успадкування всіх властивостей.","Позначення додає селектору ідентифікатор.","Оголошення з !important не може бути перевизначене іншим важливим оголошенням."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про !important правильні? Правило, яке потрібно запам’ятати: Позначене оголошення бере участь у каскаді з підвищеною важливістю.; Між двома важливими оголошеннями враховується специфічність. Варіант «Позначене оголошення бере участь у каскаді з підвищеною важливістю.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Між двома важливими оголошеннями враховується специфічність.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Позначення скасовує успадкування всіх властивостей.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Позначене оголошення бере участь у каскаді з підвищеною важливістю.; Між двома важливими оголошеннями враховується специфічність.». Варіант «Позначення додає селектору ідентифікатор.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Позначене оголошення бере участь у каскаді з підвищеною важливістю.; Між двома важливими оголошеннями враховується специфічність.». Варіант «Оголошення з !important не може бути перевизначене іншим важливим оголошенням.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Позначене оголошення бере участь у каскаді з підвищеною важливістю.; Між двома важливими оголошеннями враховується специфічність.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про успадкування правильні?',NULL,'["Успадкування використовується, коли елемент не має каскадного значення властивості.","Значення inherit можна задати властивості явно.","Дочірній елемент успадковує margin батька як стандартну поведінку.","Пряме оголошення дочірнього елемента поступається успадкованому значенню.","Усі CSS-властивості успадковуються однаково."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про успадкування правильні? Правило, яке потрібно запам’ятати: Успадкування використовується, коли елемент не має каскадного значення властивості.; Значення inherit можна задати властивості явно. Варіант «Успадкування використовується, коли елемент не має каскадного значення властивості.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Значення inherit можна задати властивості явно.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Дочірній елемент успадковує margin батька як стандартну поведінку.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Успадкування використовується, коли елемент не має каскадного значення властивості.; Значення inherit можна задати властивості явно.». Варіант «Пряме оголошення дочірнього елемента поступається успадкованому значенню.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Успадкування використовується, коли елемент не має каскадного значення властивості.; Значення inherit можна задати властивості явно.». Варіант «Усі CSS-властивості успадковуються однаково.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Успадкування використовується, коли елемент не має каскадного значення властивості.; Значення inherit можна задати властивості явно.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про :where() та :is() правильні?',NULL,'["Псевдоклас :where() має нульову специфічність.","Специфічність :is() визначає найспецифічніший селектор у списку.","Псевдоклас :where() додає вагу кожного селектора у списку.","Псевдоклас :is() має нульову специфічність для будь-якого списку.","Обидва псевдокласи вимикають каскад."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про :where() та :is() правильні? Правило, яке потрібно запам’ятати: Псевдоклас :where() має нульову специфічність.; Специфічність :is() визначає найспецифічніший селектор у списку. Варіант «Псевдоклас :where() має нульову специфічність.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Специфічність :is() визначає найспецифічніший селектор у списку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Псевдоклас :where() додає вагу кожного селектора у списку.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Псевдоклас :where() має нульову специфічність.; Специфічність :is() визначає найспецифічніший селектор у списку.». Варіант «Псевдоклас :is() має нульову специфічність для будь-якого списку.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Псевдоклас :where() має нульову специфічність.; Специфічність :is() визначає найспецифічніший селектор у списку.». Варіант «Обидва псевдокласи вимикають каскад.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Псевдоклас :where() має нульову специфічність.; Специфічність :is() визначає найспецифічніший селектор у списку.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який колір матиме текст?','<p id="message" class="text">Привіт</p>

.text { color: blue; }
#message { color: red; }','["Червоний через селектор ідентифікатора.","Синій через селектор класу.","Чорний через конфлікт оголошень.","Колір залежатиме від порядку класів у HTML."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який колір матиме текст? Правило, яке потрібно запам’ятати: Червоний через селектор ідентифікатора. Варіант «Червоний через селектор ідентифікатора.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Синій через селектор класу.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через селектор ідентифікатора.». Варіант «Чорний через конфлікт оголошень.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через селектор ідентифікатора.». Варіант «Колір залежатиме від порядку класів у HTML.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через селектор ідентифікатора.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який колір матиме елемент <span>?','<div class="panel">
  <span>Текст</span>
</div>

.panel { color: blue; }
span { color: green; }','["Зелений через пряме оголошення для <span>.","Синій через успадкування від <div>.","Чорний через відсутність класу у <span>.","Прозорий через конфлікт кольорів."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який колір матиме елемент <span>? Правило, яке потрібно запам’ятати: Зелений через пряме оголошення для <span>. Варіант «Зелений через пряме оголошення для <span>.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Синій через успадкування від <div>.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Зелений через пряме оголошення для <span>.». Варіант «Чорний через відсутність класу у <span>.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Зелений через пряме оголошення для <span>.». Варіант «Прозорий через конфлікт кольорів.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Зелений через пряме оголошення для <span>.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який колір матиме текст кнопки?','<button id="save" class="action">Зберегти</button>

#save { color: black; }
.action { color: white !important; }','["Білий через оголошення з !important.","Чорний через селектор ідентифікатора.","Сірий через стандартний стиль браузера.","Колір не буде застосовано."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який колір матиме текст кнопки? Правило, яке потрібно запам’ятати: Білий через оголошення з !important. Варіант «Білий через оголошення з !important.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Чорний через селектор ідентифікатора.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Білий через оголошення з !important.». Варіант «Сірий через стандартний стиль браузера.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Білий через оголошення з !important.». Варіант «Колір не буде застосовано.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Білий через оголошення з !important.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який колір матиме текст абзацу?','<p class="notice">Увага</p>

.notice { color: orange; }
.notice { color: purple; }','["Фіолетовий, бо пізніше правило має однакову специфічність.","Помаранчевий, бо перше правило має перевагу за однакової специфічності.","Змішаний, бо браузер поєднає два однаково специфічні оголошення.","Стандартний, бо однакова специфічність скасує обидва оголошення."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який колір матиме текст абзацу? Правило, яке потрібно запам’ятати: Фіолетовий, бо пізніше правило має однакову специфічність. Варіант «Фіолетовий, бо пізніше правило має однакову специфічність.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Помаранчевий, бо перше правило має перевагу за однакової специфічності.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Фіолетовий, бо пізніше правило має однакову специфічність.». Варіант «Змішаний, бо браузер поєднає два однаково специфічні оголошення.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Фіолетовий, бо пізніше правило має однакову специфічність.». Варіант «Стандартний, бо однакова специфічність скасує обидва оголошення.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Фіолетовий, бо пізніше правило має однакову специфічність.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який колір матиме текст?','<p id="note" style="color: red">Текст</p>

#note {
  color: blue;
}','["Червоний через вбудоване оголошення.","Синій через селектор ідентифікатора.","Зелений через успадкування.","Колір не визначено."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який колір матиме текст? Правило, яке потрібно запам’ятати: Червоний через вбудоване оголошення. Варіант «Червоний через вбудоване оголошення.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Синій через селектор ідентифікатора.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через вбудоване оголошення.». Варіант «Зелений через успадкування.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через вбудоване оголошення.». Варіант «Колір не визначено.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Червоний через вбудоване оголошення.».' FROM topics WHERE slug='cascade' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка частина блочної моделі розташована між вмістом і рамкою?',NULL,'["margin","padding","outline","gap"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яка частина блочної моделі розташована між вмістом і рамкою? Правило, яке потрібно запам’ятати: padding Варіант «margin» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «padding». Варіант «padding» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «outline» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «padding». Варіант «gap» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «padding».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка властивість задає зовнішній відступ елемента?',NULL,'["padding","border-spacing","margin","inset"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Яка властивість задає зовнішній відступ елемента? Правило, яке потрібно запам’ятати: margin Варіант «padding» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «margin». Варіант «border-spacing» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «margin». Варіант «margin» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «inset» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «margin».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке значення box-sizing включає padding і border у задану ширину?',NULL,'["content-box","initial","border-box","inherit"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Яке значення box-sizing включає padding і border у задану ширину? Правило, яке потрібно запам’ятати: border-box Варіант «content-box» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-box». Варіант «initial» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-box». Варіант «border-box» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «inherit» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-box».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка властивість задає рамку навколо елемента?',NULL,'["outline-offset","border","box-shadow","background"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яка властивість задає рамку навколо елемента? Правило, яке потрібно запам’ятати: border Варіант «outline-offset» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border». Варіант «border» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «box-shadow» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border». Варіант «background» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка область містить текст або зображення елемента?',NULL,'["Область вмісту","Область margin","Область рамки","Область outline"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка область містить текст або зображення елемента? Правило, яке потрібно запам’ятати: Область вмісту Варіант «Область вмісту» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Область margin» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Область вмісту». Варіант «Область рамки» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Область вмісту». Варіант «Область outline» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Область вмісту».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про content-box правильні?',NULL,'["Задана width визначає ширину області вмісту.","Padding і border збільшують зовнішню ширину блока.","Задана width включає margin.","Padding віднімається від ширини вмісту.","Border не бере участі в розмірі блока."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про content-box правильні? Правило, яке потрібно запам’ятати: Задана width визначає ширину області вмісту.; Padding і border збільшують зовнішню ширину блока. Варіант «Задана width визначає ширину області вмісту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Padding і border збільшують зовнішню ширину блока.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Задана width включає margin.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width визначає ширину області вмісту.; Padding і border збільшують зовнішню ширину блока.». Варіант «Padding віднімається від ширини вмісту.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width визначає ширину області вмісту.; Padding і border збільшують зовнішню ширину блока.». Варіант «Border не бере участі в розмірі блока.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width визначає ширину області вмісту.; Padding і border збільшують зовнішню ширину блока.».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про border-box правильні?',NULL,'["Задана width включає вміст, padding і border.","Збільшення padding може зменшити доступну ширину вмісту.","Margin входить до заданої width.","Border додається поверх заданої width.","Властивість width визначає лише область вмісту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про border-box правильні? Правило, яке потрібно запам’ятати: Задана width включає вміст, padding і border.; Збільшення padding може зменшити доступну ширину вмісту. Варіант «Задана width включає вміст, padding і border.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Збільшення padding може зменшити доступну ширину вмісту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Margin входить до заданої width.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width включає вміст, padding і border.; Збільшення padding може зменшити доступну ширину вмісту.». Варіант «Border додається поверх заданої width.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width включає вміст, padding і border.; Збільшення padding може зменшити доступну ширину вмісту.». Варіант «Властивість width визначає лише область вмісту.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Задана width включає вміст, padding і border.; Збільшення padding може зменшити доступну ширину вмісту.».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про вертикальні margin сусідніх блоків правильні?',NULL,'["Суміжні вертикальні відступи можуть схлопуватися.","Після схлопування зазвичай використовується більший із додатних відступів.","Горизонтальні відступи схлопуються за тим самим правилом.","Padding між блоками посилює схлопування їхніх margin.","Схлопування додає обидва додатні відступи."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про вертикальні margin сусідніх блоків правильні? Правило, яке потрібно запам’ятати: Суміжні вертикальні відступи можуть схлопуватися.; Після схлопування зазвичай використовується більший із додатних відступів. Варіант «Суміжні вертикальні відступи можуть схлопуватися.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Після схлопування зазвичай використовується більший із додатних відступів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Горизонтальні відступи схлопуються за тим самим правилом.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Суміжні вертикальні відступи можуть схлопуватися.; Після схлопування зазвичай використовується більший із додатних відступів.». Варіант «Padding між блоками посилює схлопування їхніх margin.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Суміжні вертикальні відступи можуть схлопуватися.; Після схлопування зазвичай використовується більший із додатних відступів.». Варіант «Схлопування додає обидва додатні відступи.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Суміжні вертикальні відступи можуть схлопуватися.; Після схлопування зазвичай використовується більший із додатних відступів.».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про outline правильні?',NULL,'["Outline малюється поза рамкою елемента.","Outline не збільшує розмір блока в розкладці.","Outline займає місце між padding і border.","Outline входить до width за border-box.","Outline змінює положення сусідніх елементів."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про outline правильні? Правило, яке потрібно запам’ятати: Outline малюється поза рамкою елемента.; Outline не збільшує розмір блока в розкладці. Варіант «Outline малюється поза рамкою елемента.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Outline не збільшує розмір блока в розкладці.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Outline займає місце між padding і border.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Outline малюється поза рамкою елемента.; Outline не збільшує розмір блока в розкладці.». Варіант «Outline входить до width за border-box.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Outline малюється поза рамкою елемента.; Outline не збільшує розмір блока в розкладці.». Варіант «Outline змінює положення сусідніх елементів.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Outline малюється поза рамкою елемента.; Outline не збільшує розмір блока в розкладці.».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві умови дають змогу горизонтально центрувати блок через margin?',NULL,'["Блок має визначену ширину, меншу за контейнер.","Лівий і правий margin мають значення auto.","Верхній і нижній padding мають однакові значення.","Елемент повинен мати position: absolute.","Рамка блока повинна мати нульову товщину."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві умови дають змогу горизонтально центрувати блок через margin? Правило, яке потрібно запам’ятати: Блок має визначену ширину, меншу за контейнер.; Лівий і правий margin мають значення auto. Варіант «Блок має визначену ширину, меншу за контейнер.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лівий і правий margin мають значення auto.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Верхній і нижній padding мають однакові значення.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок має визначену ширину, меншу за контейнер.; Лівий і правий margin мають значення auto.». Варіант «Елемент повинен мати position: absolute.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок має визначену ширину, меншу за контейнер.; Лівий і правий margin мають значення auto.». Варіант «Рамка блока повинна мати нульову товщину.» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Блок має визначену ширину, меншу за контейнер.; Лівий і правий margin мають значення auto.».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Якою буде зовнішня ширина блока без урахування margin?','.box {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
}','["250px","240px","210px","200px"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Якою буде зовнішня ширина блока без урахування margin? Правило, яке потрібно запам’ятати: 250px Варіант «250px» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «240px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «250px». Варіант «210px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «250px». Варіант «200px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «250px».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Якою буде ширина області вмісту?','.box {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
}','["150px","160px","190px","200px"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Якою буде ширина області вмісту? Правило, яке потрібно запам’ятати: 150px Варіант «150px» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «160px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «150px». Варіант «190px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «150px». Варіант «200px» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «150px».' FROM topics WHERE slug='box-model' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Якими будуть лівий і правий зовнішні відступи блока?','.container { width: 500px; }
.box {
