INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Від розміру шрифту якого елемента залежить одиниця rem?',NULL,'["Поточного елемента","Батьківського елемента","Кореневого елемента","Найближчого блока"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Від розміру шрифту якого елемента залежить одиниця rem? Правило, яке потрібно запам’ятати: Кореневого елемента Варіант «Поточного елемента» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Кореневого елемента». Варіант «Батьківського елемента» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Кореневого елемента». Варіант «Кореневого елемента» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Найближчого блока» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «Кореневого елемента».' FROM topics WHERE slug='units' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка одиниця дорівнює одному відсотку ширини viewport?',NULL,'["vh","vw","vmin","%"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яка одиниця дорівнює одному відсотку ширини viewport? Правило, яке потрібно запам’ятати: vw Варіант «vh» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «vw». Варіант «vw» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «vmin» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «vw». Варіант «%» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «vw».' FROM topics WHERE slug='units' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
