INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка властивість заокруглює кути рамки?',NULL,'["border-spacing","border-radius","outline-offset","clip-path"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яка властивість заокруглює кути рамки? Правило, яке потрібно запам’ятати: border-radius Варіант «border-spacing» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-radius». Варіант «border-radius» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «outline-offset» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-radius». Варіант «clip-path» неправильний: він суперечить перевірюваному правилу CSS. Для цієї умови правильні положення: «border-radius».' FROM topics WHERE slug='colors-backgrounds-borders' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
