INSERT INTO technologies(slug,name) VALUES ('git','Git') ON CONFLICT (slug) DO NOTHING;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-basics','Основи Git','Репозиторій, робоче дерево, індекс, коміти та посилання HEAD.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-commands','Базові команди','Ініціалізація, перевірка стану, підготовка, коміти та перегляд змін.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-branches','Branches','Створення, перемикання, об’єднання та видалення гілок.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-remotes','Remote repositories','Віддалені репозиторії, clone, fetch, pull, push та tracking-гілки.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'github-workflow','GitHub workflow','Гілки, pull request, перевірки, review та інтеграція змін.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'merge-conflicts','Merge conflicts','Причини конфліктів, маркери, розв’язання та скасування merge.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-undo-history','Undo і зміна історії','Відновлення файлів, reset, revert, amend і reflog.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'gitignore','.gitignore','Шаблони ігнорування, винятки, області дії та відстежувані файли.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
INSERT INTO topics(technology_id,slug,name,description) SELECT id,'git-rebase','Rebase','Перенесення комітів, інтерактивна зміна послідовності та конфлікти.' FROM technologies WHERE slug='git' ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description;
UPDATE questions SET is_active=FALSE WHERE topic_id IN (SELECT topics.id FROM topics JOIN technologies ON technologies.id=topics.technology_id WHERE technologies.slug='git');
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Для чого використовують Git?',NULL,'["Для керування історією версій файлів","Для зберігання лише останньої копії проєкту","Для передавання файлів без фіксації змін","Для призначення прав доступу до каталогів"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Для чого використовують Git? Правило, яке потрібно запам’ятати: Для керування історією версій файлів Варіант «Для керування історією версій файлів» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Для зберігання лише останньої копії проєкту» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для керування історією версій файлів». Варіант «Для передавання файлів без фіксації змін» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для керування історією версій файлів». Варіант «Для призначення прав доступу до каталогів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для керування історією версій файлів».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що зберігається в каталозі .git?',NULL,'["Службові дані та історія репозиторію","Лише файли поточного робочого дерева","Лише шаблони ігнорування проєкту","Копія тільки останньої віддаленої гілки"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що зберігається в каталозі .git? Правило, яке потрібно запам’ятати: Службові дані та історія репозиторію Варіант «Службові дані та історія репозиторію» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише файли поточного робочого дерева» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Службові дані та історія репозиторію». Варіант «Лише шаблони ігнорування проєкту» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Службові дані та історія репозиторію». Варіант «Копія тільки останньої віддаленої гілки» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Службові дані та історія репозиторію».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що фіксує коміт у Git?',NULL,'["Стан підготовлених файлів","Усі підготовлені й непідготовлені зміни","Поточний стан лише віддаленої гілки","Правила ігнорування без вмісту файлів"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що фіксує коміт у Git? Правило, яке потрібно запам’ятати: Стан підготовлених файлів Варіант «Стан підготовлених файлів» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Усі підготовлені й непідготовлені зміни» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Стан підготовлених файлів». Варіант «Поточний стан лише віддаленої гілки» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Стан підготовлених файлів». Варіант «Правила ігнорування без вмісту файлів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Стан підготовлених файлів».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Як називається область, у якій користувач редагує файли проєкту?',NULL,'["Робоче дерево","Віддалений репозиторій","Журнал посилань","Об’єктна база сервера"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Як називається область, у якій користувач редагує файли проєкту? Правило, яке потрібно запам’ятати: Робоче дерево Варіант «Робоче дерево» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Віддалений репозиторій» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево». Варіант «Журнал посилань» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево». Варіант «Об’єктна база сервера» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Для чого потрібен індекс Git?',NULL,'["Для підготовки вмісту наступного коміту","Для зберігання remote-tracking посилань","Для ведення журналу переміщень HEAD","Для визначення ігнорованих шляхів"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Для чого потрібен індекс Git? Правило, яке потрібно запам’ятати: Для підготовки вмісту наступного коміту Варіант «Для підготовки вмісту наступного коміту» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Для зберігання remote-tracking посилань» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для підготовки вмісту наступного коміту». Варіант «Для ведення журналу переміщень HEAD» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для підготовки вмісту наступного коміту». Варіант «Для визначення ігнорованих шляхів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для підготовки вмісту наступного коміту».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві області користувач змінює під час підготовки нового коміту?',NULL,'["Робоче дерево","Індекс","Remote-tracking гілка","Журнал reflog","Сховище stash"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві області користувач змінює під час підготовки нового коміту? Правило, яке потрібно запам’ятати: Робоче дерево; Індекс Варіант «Робоче дерево» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Індекс» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Remote-tracking гілка» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево; Індекс». Варіант «Журнал reflog» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево; Індекс». Варіант «Сховище stash» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Робоче дерево; Індекс».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують коміт Git?',NULL,'["Коміт містить знімок підготовленого стану проєкту.","Некореневий коміт зберігає посилання на батьківський коміт.","Коміт містить лише назви змінених файлів.","Коміт існує тільки після відправлення на GitHub.","Коміт змінює глобальну конфігурацію Git."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують коміт Git? Правило, яке потрібно запам’ятати: Коміт містить знімок підготовленого стану проєкту.; Некореневий коміт зберігає посилання на батьківський коміт. Варіант «Коміт містить знімок підготовленого стану проєкту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Некореневий коміт зберігає посилання на батьківський коміт.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коміт містить лише назви змінених файлів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт містить знімок підготовленого стану проєкту.; Некореневий коміт зберігає посилання на батьківський коміт.». Варіант «Коміт існує тільки після відправлення на GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт містить знімок підготовленого стану проєкту.; Некореневий коміт зберігає посилання на батьківський коміт.». Варіант «Коміт змінює глобальну конфігурацію Git.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт містить знімок підготовленого стану проєкту.; Некореневий коміт зберігає посилання на батьківський коміт.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують розподілений репозиторій Git?',NULL,'["Локальна копія може містити історію проєкту.","Коміти можна створювати без з’єднання з віддаленим сервером.","Історія зберігається тільки в GitHub.","Кожна команда потребує доступу до мережі.","Локальний репозиторій містить лише останню версію файлів."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують розподілений репозиторій Git? Правило, яке потрібно запам’ятати: Локальна копія може містити історію проєкту.; Коміти можна створювати без з’єднання з віддаленим сервером. Варіант «Локальна копія може містити історію проєкту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коміти можна створювати без з’єднання з віддаленим сервером.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Історія зберігається тільки в GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальна копія може містити історію проєкту.; Коміти можна створювати без з’єднання з віддаленим сервером.». Варіант «Кожна команда потребує доступу до мережі.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальна копія може містити історію проєкту.; Коміти можна створювати без з’єднання з віддаленим сервером.». Варіант «Локальний репозиторій містить лише останню версію файлів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальна копія може містити історію проєкту.; Коміти можна створювати без з’єднання з віддаленим сервером.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно розрізняють змінений і підготовлений файл?',NULL,'["Змінений файл у робочому дереві відрізняється від його версії в індексі.","Підготовлена версія файлу в індексі відрізняється від версії в HEAD.","Змінений файл уже міститься в новому коміті.","Підготовлений файл уже відправлено до origin.","Обидва стани означають, що файл не відстежується."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно розрізняють змінений і підготовлений файл? Правило, яке потрібно запам’ятати: Змінений файл у робочому дереві відрізняється від його версії в індексі.; Підготовлена версія файлу в індексі відрізняється від версії в HEAD. Варіант «Змінений файл у робочому дереві відрізняється від його версії в індексі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Підготовлена версія файлу в індексі відрізняється від версії в HEAD.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Змінений файл уже міститься в новому коміті.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінений файл у робочому дереві відрізняється від його версії в індексі.; Підготовлена версія файлу в індексі відрізняється від версії в HEAD.». Варіант «Підготовлений файл уже відправлено до origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінений файл у робочому дереві відрізняється від його версії в індексі.; Підготовлена версія файлу в індексі відрізняється від версії в HEAD.». Варіант «Обидва стани означають, що файл не відстежується.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінений файл у робочому дереві відрізняється від його версії в індексі.; Підготовлена версія файлу в індексі відрізняється від версії в HEAD.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про HEAD правильні?',NULL,'["HEAD указує на поточне положення в історії.","У звичайному стані HEAD посилається на поточну гілку.","HEAD зберігає список ігнорованих файлів.","HEAD є назвою віддаленого репозиторію.","HEAD містить повідомлення кожного коміту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про HEAD правильні? Правило, яке потрібно запам’ятати: HEAD указує на поточне положення в історії.; У звичайному стані HEAD посилається на поточну гілку. Варіант «HEAD указує на поточне положення в історії.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «У звичайному стані HEAD посилається на поточну гілку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «HEAD зберігає список ігнорованих файлів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує на поточне положення в історії.; У звичайному стані HEAD посилається на поточну гілку.». Варіант «HEAD є назвою віддаленого репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує на поточне положення в історії.; У звичайному стані HEAD посилається на поточну гілку.». Варіант «HEAD містить повідомлення кожного коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує на поточне положення в історії.; У звичайному стані HEAD посилається на поточну гілку.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження відрізняють Git від централізованої системи контролю версій?',NULL,'["Локальний репозиторій може містити повну історію.","Розробник може створювати локальні коміти без мережі.","Для кожного коміту потрібне з’єднання з центральним сервером.","Локальна копія містить лише файли робочого дерева.","Індекс зберігається на GitHub.","Гілки можна створювати лише у вебінтерфейсі."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження відрізняють Git від централізованої системи контролю версій? Правило, яке потрібно запам’ятати: Локальний репозиторій може містити повну історію.; Розробник може створювати локальні коміти без мережі. Варіант «Локальний репозиторій може містити повну історію.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Розробник може створювати локальні коміти без мережі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Для кожного коміту потрібне з’єднання з центральним сервером.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальний репозиторій може містити повну історію.; Розробник може створювати локальні коміти без мережі.». Варіант «Локальна копія містить лише файли робочого дерева.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальний репозиторій може містити повну історію.; Розробник може створювати локальні коміти без мережі.». Варіант «Індекс зберігається на GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальний репозиторій може містити повну історію.; Розробник може створювати локальні коміти без мережі.». Варіант «Гілки можна створювати лише у вебінтерфейсі.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Локальний репозиторій може містити повну історію.; Розробник може створювати локальні коміти без мережі.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження правильно описують зв’язок індексу та коміту?',NULL,'["Індекс визначає вміст наступного коміту.","Коміт записує підготовлений стан як новий знімок.","Індекс містить усю віддалену історію.","Коміт додає до історії всі непідготовлені зміни.","Індекс замінює робоче дерево.","Коміт очищає файли проєкту після запису."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують зв’язок індексу та коміту? Правило, яке потрібно запам’ятати: Індекс визначає вміст наступного коміту.; Коміт записує підготовлений стан як новий знімок. Варіант «Індекс визначає вміст наступного коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коміт записує підготовлений стан як новий знімок.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Індекс містить усю віддалену історію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Індекс визначає вміст наступного коміту.; Коміт записує підготовлений стан як новий знімок.». Варіант «Коміт додає до історії всі непідготовлені зміни.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Індекс визначає вміст наступного коміту.; Коміт записує підготовлений стан як новий знімок.». Варіант «Індекс замінює робоче дерево.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Індекс визначає вміст наступного коміту.; Коміт записує підготовлений стан як новий знімок.». Варіант «Коміт очищає файли проєкту після запису.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Індекс визначає вміст наступного коміту.; Коміт записує підготовлений стан як новий знімок.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження правильно описують зв’язок комітів і гілок?',NULL,'["Коміт може посилатися на один або кілька батьківських комітів.","Гілка зберігає рухоме посилання на свій кінцевий коміт.","Кожний коміт містить URL віддаленого репозиторію.","Гілка зберігає окремий повний набір Git-об’єктів.","Коміт посилається на файл .gitignore як на свого батька.","Назва гілки входить до вмісту кожного її коміту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують зв’язок комітів і гілок? Правило, яке потрібно запам’ятати: Коміт може посилатися на один або кілька батьківських комітів.; Гілка зберігає рухоме посилання на свій кінцевий коміт. Варіант «Коміт може посилатися на один або кілька батьківських комітів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Гілка зберігає рухоме посилання на свій кінцевий коміт.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кожний коміт містить URL віддаленого репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт може посилатися на один або кілька батьківських комітів.; Гілка зберігає рухоме посилання на свій кінцевий коміт.». Варіант «Гілка зберігає окремий повний набір Git-об’єктів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт може посилатися на один або кілька батьківських комітів.; Гілка зберігає рухоме посилання на свій кінцевий коміт.». Варіант «Коміт посилається на файл .gitignore як на свого батька.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт може посилатися на один або кілька батьківських комітів.; Гілка зберігає рухоме посилання на свій кінцевий коміт.». Варіант «Назва гілки входить до вмісту кожного її коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коміт може посилатися на один або кілька батьківських комітів.; Гілка зберігає рухоме посилання на свій кінцевий коміт.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про ідентифікатор коміту правильні?',NULL,'["Він обчислюється з вмісту та метаданих об’єкта.","Зміна записаного вмісту приводить до іншого ідентифікатора.","Його задають лише порядковим номером коміту.","Він збігається з назвою поточної гілки.","Його створюють тільки під час git push.","Після git commit --amend він залишається попереднім."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про ідентифікатор коміту правильні? Правило, яке потрібно запам’ятати: Він обчислюється з вмісту та метаданих об’єкта.; Зміна записаного вмісту приводить до іншого ідентифікатора. Варіант «Він обчислюється з вмісту та метаданих об’єкта.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зміна записаного вмісту приводить до іншого ідентифікатора.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Його задають лише порядковим номером коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він обчислюється з вмісту та метаданих об’єкта.; Зміна записаного вмісту приводить до іншого ідентифікатора.». Варіант «Він збігається з назвою поточної гілки.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він обчислюється з вмісту та метаданих об’єкта.; Зміна записаного вмісту приводить до іншого ідентифікатора.». Варіант «Його створюють тільки під час git push.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він обчислюється з вмісту та метаданих об’єкта.; Зміна записаного вмісту приводить до іншого ідентифікатора.». Варіант «Після git commit --amend він залишається попереднім.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він обчислюється з вмісту та метаданих об’єкта.; Зміна записаного вмісту приводить до іншого ідентифікатора.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження описують detached HEAD?',NULL,'["HEAD указує безпосередньо на коміт, а не на локальну гілку.","Нові коміти не пересувають наявну локальну гілку без перемикання на неї.","Робоче дерево видаляється після від’єднання HEAD від гілки.","Git втрачає можливість виконувати локальні команди без мережі.","Індекс перетворюється на окрему remote-tracking гілку.","Усі коміти репозиторію втрачають посилання на батьків."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження описують detached HEAD? Правило, яке потрібно запам’ятати: HEAD указує безпосередньо на коміт, а не на локальну гілку.; Нові коміти не пересувають наявну локальну гілку без перемикання на неї. Варіант «HEAD указує безпосередньо на коміт, а не на локальну гілку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Нові коміти не пересувають наявну локальну гілку без перемикання на неї.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Робоче дерево видаляється після від’єднання HEAD від гілки.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує безпосередньо на коміт, а не на локальну гілку.; Нові коміти не пересувають наявну локальну гілку без перемикання на неї.». Варіант «Git втрачає можливість виконувати локальні команди без мережі.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує безпосередньо на коміт, а не на локальну гілку.; Нові коміти не пересувають наявну локальну гілку без перемикання на неї.». Варіант «Індекс перетворюється на окрему remote-tracking гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує безпосередньо на коміт, а не на локальну гілку.; Нові коміти не пересувають наявну локальну гілку без перемикання на неї.». Варіант «Усі коміти репозиторію втрачають посилання на батьків.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «HEAD указує безпосередньо на коміт, а не на локальну гілку.; Нові коміти не пересувають наявну локальну гілку без перемикання на неї.».' FROM topics WHERE slug='git-basics' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда створює Git-репозиторій у поточному каталозі?',NULL,'["git init","git status","git add","git log"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда створює Git-репозиторій у поточному каталозі? Правило, яке потрібно запам’ятати: git init Варіант «git init» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git status» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git init». Варіант «git add» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git init». Варіант «git log» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git init».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує стан робочого дерева та індексу?',NULL,'["git commit","git status","git clone","git branch"]'::jsonb,'[1]'::jsonb,'Питання перевіряє: Яка команда показує стан робочого дерева та індексу? Правило, яке потрібно запам’ятати: git status Варіант «git commit» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status». Варіант «git status» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git clone» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status». Варіант «git branch» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда додає файл app.js до індексу?',NULL,'["git add app.js","git log app.js","git init app.js","git push app.js"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда додає файл app.js до індексу? Правило, яке потрібно запам’ятати: git add app.js Варіант «git add app.js» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git log app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js». Варіант «git init app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js». Варіант «git push app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда створює коміт із повідомленням Add header?',NULL,'["git commit -m \"Add header\"","git add -m \"Add header\"","git status -m \"Add header\"","git log -m \"Add header\""]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда створює коміт із повідомленням Add header? Правило, яке потрібно запам’ятати: git commit -m "Add header" Варіант «git commit -m "Add header"» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git add -m "Add header"» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit -m "Add header"». Варіант «git status -m "Add header"» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit -m "Add header"». Варіант «git log -m "Add header"» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit -m "Add header"».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує історію комітів?',NULL,'["git diff","git restore","git log","git remote"]'::jsonb,'[2]'::jsonb,'Питання перевіряє: Яка команда показує історію комітів? Правило, яке потрібно запам’ятати: git log Варіант «git diff» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git log». Варіант «git restore» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git log». Варіант «git log» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git log».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує команда git add app.js?',NULL,'["Копіює поточний вміст app.js до індексу.","Готує зміни app.js для наступного коміту.","Створює коміт з app.js.","Відправляє app.js до віддаленого репозиторію.","Видаляє попередні версії app.js з історії."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує команда git add app.js? Правило, яке потрібно запам’ятати: Копіює поточний вміст app.js до індексу.; Готує зміни app.js для наступного коміту. Варіант «Копіює поточний вміст app.js до індексу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Готує зміни app.js для наступного коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Створює коміт з app.js.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Копіює поточний вміст app.js до індексу.; Готує зміни app.js для наступного коміту.». Варіант «Відправляє app.js до віддаленого репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Копіює поточний вміст app.js до індексу.; Готує зміни app.js для наступного коміту.». Варіант «Видаляє попередні версії app.js з історії.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Копіює поточний вміст app.js до індексу.; Готує зміни app.js для наступного коміту.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два типи змін може окремо показати git status?',NULL,'["Зміни, підготовлені до коміту","Зміни, не підготовлені до коміту","Патч кожного попереднього коміту","Повний список remote-tracking гілок","Вміст об’єктів віддаленого репозиторію"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два типи змін може окремо показати git status? Правило, яке потрібно запам’ятати: Зміни, підготовлені до коміту; Зміни, не підготовлені до коміту Варіант «Зміни, підготовлені до коміту» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зміни, не підготовлені до коміту» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Патч кожного попереднього коміту» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни, підготовлені до коміту; Зміни, не підготовлені до коміту». Варіант «Повний список remote-tracking гілок» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни, підготовлені до коміту; Зміни, не підготовлені до коміту». Варіант «Вміст об’єктів віддаленого репозиторію» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни, підготовлені до коміту; Зміни, не підготовлені до коміту».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві команди порівнюють зміни до створення коміту?',NULL,'["git diff показує непідготовлені зміни.","git diff --staged показує підготовлені зміни.","git log показує непідготовлені рядки.","git init порівнює індекс із комітом.","git push порівнює два локальні файли."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві команди порівнюють зміни до створення коміту? Правило, яке потрібно запам’ятати: git diff показує непідготовлені зміни.; git diff --staged показує підготовлені зміни. Варіант «git diff показує непідготовлені зміни.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git diff --staged показує підготовлені зміни.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git log показує непідготовлені рядки.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує непідготовлені зміни.; git diff --staged показує підготовлені зміни.». Варіант «git init порівнює індекс із комітом.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує непідготовлені зміни.; git diff --staged показує підготовлені зміни.». Варіант «git push порівнює два локальні файли.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує непідготовлені зміни.; git diff --staged показує підготовлені зміни.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві умови потрібні для звичайного створення змістовного коміту?',NULL,'["Потрібно підготувати зміни в індексі.","Потрібно вказати або відкрити редактор для повідомлення коміту.","Потрібно налаштувати віддалений origin.","Потрібно видалити всі непідготовлені зміни.","Потрібно перейти на гілку main."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві умови потрібні для звичайного створення змістовного коміту? Правило, яке потрібно запам’ятати: Потрібно підготувати зміни в індексі.; Потрібно вказати або відкрити редактор для повідомлення коміту. Варіант «Потрібно підготувати зміни в індексі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно вказати або відкрити редактор для повідомлення коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно налаштувати віддалений origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно підготувати зміни в індексі.; Потрібно вказати або відкрити редактор для повідомлення коміту.». Варіант «Потрібно видалити всі непідготовлені зміни.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно підготувати зміни в індексі.; Потрібно вказати або відкрити редактор для повідомлення коміту.». Варіант «Потрібно перейти на гілку main.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно підготувати зміни в індексі.; Потрібно вказати або відкрити редактор для повідомлення коміту.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві команди допомагають переглянути останні зміни та історію?',NULL,'["git diff показує відмінності між станами.","git log показує послідовність комітів.","git add показує авторів комітів.","git init показує зміни рядків.","git restore показує віддалені гілки."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві команди допомагають переглянути останні зміни та історію? Правило, яке потрібно запам’ятати: git diff показує відмінності між станами.; git log показує послідовність комітів. Варіант «git diff показує відмінності між станами.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git log показує послідовність комітів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git add показує авторів комітів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує відмінності між станами.; git log показує послідовність комітів.». Варіант «git init показує зміни рядків.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує відмінності між станами.; git log показує послідовність комітів.». Варіант «git restore показує віддалені гілки.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git diff показує відмінності між станами.; git log показує послідовність комітів.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде стан notes.txt після виконання команд?','git init
# Створено файл notes.txt
git add notes.txt
git status','["Файл буде підготовлений до першого коміту.","Файл буде записаний у новому коміті.","Файл залишиться поза репозиторієм без відстеження.","Файл буде відправлений до origin."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде стан notes.txt після виконання команд? Правило, яке потрібно запам’ятати: Файл буде підготовлений до першого коміту. Варіант «Файл буде підготовлений до першого коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Файл буде записаний у новому коміті.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл буде підготовлений до першого коміту.». Варіант «Файл залишиться поза репозиторієм без відстеження.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл буде підготовлений до першого коміту.». Варіант «Файл буде відправлений до origin.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл буде підготовлений до першого коміту.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які зміни покаже git diff після цих дій?','# До page.txt додано рядок header
git add page.txt
# До page.txt додано рядок footer
git diff','["Лише рядок footer, доданий після git add.","Лише рядок header, підготовлений командою git add.","Обидва рядки як підготовлені зміни.","Команда не покаже відмінностей."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Які зміни покаже git diff після цих дій? Правило, яке потрібно запам’ятати: Лише рядок footer, доданий після git add. Варіант «Лише рядок footer, доданий після git add.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише рядок header, підготовлений командою git add.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише рядок footer, доданий після git add.». Варіант «Обидва рядки як підготовлені зміни.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише рядок footer, доданий після git add.». Варіант «Команда не покаже відмінностей.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Лише рядок footer, доданий після git add.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що буде записано в новому коміті?','# У app.js внесено зміну A
git add app.js
# У app.js внесено зміну B
git commit -m "Update app"','["Підготовлену версію app.js зі зміною A.","Робочу версію app.js зі змінами A і B.","Лише непідготовлену зміну B.","Порожній знімок без app.js."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що буде записано в новому коміті? Правило, яке потрібно запам’ятати: Підготовлену версію app.js зі зміною A. Варіант «Підготовлену версію app.js зі зміною A.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Робочу версію app.js зі змінами A і B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Підготовлену версію app.js зі зміною A.». Варіант «Лише непідготовлену зміну B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Підготовлену версію app.js зі зміною A.». Варіант «Порожній знімок без app.js.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Підготовлену версію app.js зі зміною A.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що покаже команда git log --oneline -2?','git log --oneline -2
# У репозиторії є щонайменше три коміти','["Два найновіші коміти у скороченому форматі.","Два найстаріші коміти з повними патчами.","Два непідготовлені файли.","Дві віддалені гілки."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що покаже команда git log --oneline -2? Правило, яке потрібно запам’ятати: Два найновіші коміти у скороченому форматі. Варіант «Два найновіші коміти у скороченому форматі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Два найстаріші коміти з повними патчами.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Два найновіші коміти у скороченому форматі.». Варіант «Два непідготовлені файли.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Два найновіші коміти у скороченому форматі.». Варіант «Дві віддалені гілки.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Два найновіші коміти у скороченому форматі.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який стан матиме index.html після виконання команд?','# Зміни відстежуваного index.html підготовлено в індексі
git restore --staged index.html
git status','["Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим.","Файл залишиться підготовленим в індексі для наступного коміту.","Поточну зміну файлу буде одразу записано в новому коміті.","Відстежуваний файл після цієї команди стане невідстежуваним."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який стан матиме index.html після виконання команд? Правило, яке потрібно запам’ятати: Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим. Варіант «Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Файл залишиться підготовленим в індексі для наступного коміту.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим.». Варіант «Поточну зміну файлу буде одразу записано в новому коміті.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим.». Варіант «Відстежуваний файл після цієї команди стане невідстежуваним.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Файл залишиться зміненим у робочому дереві, але більше не буде підготовленим.».' FROM topics WHERE slug='git-commands' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує список локальних гілок?',NULL,'["git branch","git status","git remote","git fetch"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда показує список локальних гілок? Правило, яке потрібно запам’ятати: git branch Варіант «git branch» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git status» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git branch». Варіант «git remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git branch». Варіант «git fetch» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git branch».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда перемикає робоче дерево на гілку feature?',NULL,'["git switch feature","git merge feature","git branch -d feature","git push feature"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда перемикає робоче дерево на гілку feature? Правило, яке потрібно запам’ятати: git switch feature Варіант «git switch feature» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git merge feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch feature». Варіант «git branch -d feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch feature». Варіант «git push feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch feature».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда створює гілку feature та одразу перемикається на неї?',NULL,'["git switch -c feature","git branch -d feature","git merge -c feature","git remote add feature"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда створює гілку feature та одразу перемикається на неї? Правило, яке потрібно запам’ятати: git switch -c feature Варіант «git switch -c feature» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git branch -d feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch -c feature». Варіант «git merge -c feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch -c feature». Варіант «git remote add feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git switch -c feature».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда об’єднує гілку feature з поточною гілкою?',NULL,'["git merge feature","git switch feature","git fetch feature","git init feature"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда об’єднує гілку feature з поточною гілкою? Правило, яке потрібно запам’ятати: git merge feature Варіант «git merge feature» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git switch feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge feature». Варіант «git fetch feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge feature». Варіант «git init feature» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge feature».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що позначає зірочка у виведенні git branch?',NULL,'["Поточну гілку","Віддалену гілку","Гілку з конфліктом","Захищену гілку"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що позначає зірочка у виведенні git branch? Правило, яке потрібно запам’ятати: Поточну гілку Варіант «Поточну гілку» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Віддалену гілку» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточну гілку». Варіант «Гілку з конфліктом» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточну гілку». Варіант «Захищену гілку» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточну гілку».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про гілку Git правильні?',NULL,'["Гілка є рухомим посиланням на коміт.","Новий коміт пересуває поточну гілку на себе.","Гілка містить окрему копію кожного файлу поза об’єктною базою.","Назва гілки визначає URL віддаленого репозиторію.","Гілка може посилатися лише на кореневий коміт."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про гілку Git правильні? Правило, яке потрібно запам’ятати: Гілка є рухомим посиланням на коміт.; Новий коміт пересуває поточну гілку на себе. Варіант «Гілка є рухомим посиланням на коміт.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Новий коміт пересуває поточну гілку на себе.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Гілка містить окрему копію кожного файлу поза об’єктною базою.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілка є рухомим посиланням на коміт.; Новий коміт пересуває поточну гілку на себе.». Варіант «Назва гілки визначає URL віддаленого репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілка є рухомим посиланням на коміт.; Новий коміт пересуває поточну гілку на себе.». Варіант «Гілка може посилатися лише на кореневий коміт.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілка є рухомим посиланням на коміт.; Новий коміт пересуває поточну гілку на себе.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git switch -c feature?',NULL,'["Створює локальну гілку feature.","Перемикає HEAD і робоче дерево на feature.","Об’єднує feature з попередньою гілкою.","Відправляє feature до origin.","Видаляє попередню гілку."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git switch -c feature? Правило, яке потрібно запам’ятати: Створює локальну гілку feature.; Перемикає HEAD і робоче дерево на feature. Варіант «Створює локальну гілку feature.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Перемикає HEAD і робоче дерево на feature.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Об’єднує feature з попередньою гілкою.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює локальну гілку feature.; Перемикає HEAD і робоче дерево на feature.». Варіант «Відправляє feature до origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює локальну гілку feature.; Перемикає HEAD і робоче дерево на feature.». Варіант «Видаляє попередню гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює локальну гілку feature.; Перемикає HEAD і робоче дерево на feature.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві умови описують fast-forward merge?',NULL,'["Поточна гілка не має власних нових комітів після точки розходження.","Посилання поточної гілки можна пересунути вперед без merge-коміту.","Обидві гілки мають конфліктні зміни одного рядка.","Git повинен створити коміт із двома батьками.","Цільова гілка має бути віддаленою."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві умови описують fast-forward merge? Правило, яке потрібно запам’ятати: Поточна гілка не має власних нових комітів після точки розходження.; Посилання поточної гілки можна пересунути вперед без merge-коміту. Варіант «Поточна гілка не має власних нових комітів після точки розходження.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Посилання поточної гілки можна пересунути вперед без merge-коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Обидві гілки мають конфліктні зміни одного рядка.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка не має власних нових комітів після точки розходження.; Посилання поточної гілки можна пересунути вперед без merge-коміту.». Варіант «Git повинен створити коміт із двома батьками.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка не має власних нових комітів після точки розходження.; Посилання поточної гілки можна пересунути вперед без merge-коміту.». Варіант «Цільова гілка має бути віддаленою.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка не має власних нових комітів після точки розходження.; Посилання поточної гілки можна пересунути вперед без merge-коміту.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії потрібні, щоб додати feature до main?',NULL,'["Потрібно перейти на main.","Потрібно виконати git merge feature.","Потрібно видалити feature перед об’єднанням.","Потрібно виконати git init feature.","Потрібно перейменувати main на feature."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії потрібні, щоб додати feature до main? Правило, яке потрібно запам’ятати: Потрібно перейти на main.; Потрібно виконати git merge feature. Варіант «Потрібно перейти на main.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно виконати git merge feature.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно видалити feature перед об’єднанням.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно перейти на main.; Потрібно виконати git merge feature.». Варіант «Потрібно виконати git init feature.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно перейти на main.; Потрібно виконати git merge feature.». Варіант «Потрібно перейменувати main на feature.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно перейти на main.; Потрібно виконати git merge feature.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про git branch -d feature правильні?',NULL,'["Команда видаляє посилання локальної гілки feature.","Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку.","Команда видаляє віддалену гілку feature з репозиторію origin.","Команда видаляє всі коміти feature з інших локальних гілок.","Команда перемикає HEAD і робоче дерево на гілку feature."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про git branch -d feature правильні? Правило, яке потрібно запам’ятати: Команда видаляє посилання локальної гілки feature.; Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку. Варіант «Команда видаляє посилання локальної гілки feature.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Команда видаляє віддалену гілку feature з репозиторію origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда видаляє посилання локальної гілки feature.; Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку.». Варіант «Команда видаляє всі коміти feature з інших локальних гілок.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда видаляє посилання локальної гілки feature.; Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку.». Варіант «Команда перемикає HEAD і робоче дерево на гілку feature.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда видаляє посилання локальної гілки feature.; Команда відмовиться видалити feature, якщо вона не об’єднана в upstream-гілку або, без upstream, у поточну гілку.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','На який коміт указуватимуть main і feature після виконання команд?','# main указує на коміт A
git switch -c feature
# Створено коміт B у feature','["main на A, feature на B.","main і feature на B.","main на B, feature на A.","Обидві гілки на A без нового коміту."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: На який коміт указуватимуть main і feature після виконання команд? Правило, яке потрібно запам’ятати: main на A, feature на B. Варіант «main на A, feature на B.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «main і feature на B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main на A, feature на B.». Варіант «main на B, feature на A.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main на A, feature на B.». Варіант «Обидві гілки на A без нового коміту.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main на A, feature на B.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який результат матиме об’єднання?','git switch main
git merge feature
# Конфліктів немає','["main міститиме зміни feature після merge.","feature буде видалено до merge.","HEAD залишиться на feature.","Коміт main буде відкинуто."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який результат матиме об’єднання? Правило, яке потрібно запам’ятати: main міститиме зміни feature після merge. Варіант «main міститиме зміни feature після merge.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «feature буде видалено до merge.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main міститиме зміни feature після merge.». Варіант «HEAD залишиться на feature.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main міститиме зміни feature після merge.». Варіант «Коміт main буде відкинуто.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «main міститиме зміни feature після merge.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що станеться під час цього fast-forward merge?','# main: A
# feature: A-B-C
git switch main
git merge feature','["Посилання main пересунеться на коміт C без окремого merge-коміту.","Git створить merge-коміт із двома батьками.","Коміт C буде скопійовано з новим ідентифікатором.","Гілку feature буде видалено."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що станеться під час цього fast-forward merge? Правило, яке потрібно запам’ятати: Посилання main пересунеться на коміт C без окремого merge-коміту. Варіант «Посилання main пересунеться на коміт C без окремого merge-коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Git створить merge-коміт із двома батьками.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Посилання main пересунеться на коміт C без окремого merge-коміту.». Варіант «Коміт C буде скопійовано з новим ідентифікатором.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Посилання main пересунеться на коміт C без окремого merge-коміту.». Варіант «Гілку feature буде видалено.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Посилання main пересунеться на коміт C без окремого merge-коміту.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде результат видалення гілки feature?','git switch main
# feature містить необ’єднаний коміт B
git branch -d feature','["Git відмовиться видалити гілку через необ’єднані зміни.","Git видалить feature разом із main.","Git об’єднає feature з main і видалить її.","Git видалить віддалену гілку origin/feature."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде результат видалення гілки feature? Правило, яке потрібно запам’ятати: Git відмовиться видалити гілку через необ’єднані зміни. Варіант «Git відмовиться видалити гілку через необ’єднані зміни.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Git видалить feature разом із main.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git відмовиться видалити гілку через необ’єднані зміни.». Варіант «Git об’єднає feature з main і видалить її.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git відмовиться видалити гілку через необ’єднані зміни.». Варіант «Git видалить віддалену гілку origin/feature.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git відмовиться видалити гілку через необ’єднані зміни.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який тип коміту з’явиться після успішного об’єднання розбіжних гілок?','# main: A-M
# feature: A-F
git switch main
git merge feature
# Конфлікти відсутні','["Merge-коміт із двома батьками.","Кореневий коміт без батьків.","Коміт, що видаляє обидві гілки.","Коміт із новим віддаленим URL."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який тип коміту з’явиться після успішного об’єднання розбіжних гілок? Правило, яке потрібно запам’ятати: Merge-коміт із двома батьками. Варіант «Merge-коміт із двома батьками.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кореневий коміт без батьків.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Merge-коміт із двома батьками.». Варіант «Коміт, що видаляє обидві гілки.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Merge-коміт із двома батьками.». Варіант «Коміт із новим віддаленим URL.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Merge-коміт із двома батьками.».' FROM topics WHERE slug='git-branches' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує назви та URL віддалених репозиторіїв?',NULL,'["git remote -v","git branch -v","git status -v","git log -v"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда показує назви та URL віддалених репозиторіїв? Правило, яке потрібно запам’ятати: git remote -v Варіант «git remote -v» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git branch -v» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git remote -v». Варіант «git status -v» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git remote -v». Варіант «git log -v» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git remote -v».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яку назву зазвичай отримує початковий віддалений репозиторій після git clone?',NULL,'["origin","upstream","source","remote"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яку назву зазвичай отримує початковий віддалений репозиторій після git clone? Правило, яке потрібно запам’ятати: origin Варіант «origin» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «upstream» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «origin». Варіант «source» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «origin». Варіант «remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «origin».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда завантажує об’єкти та посилання з origin без об’єднання з поточною гілкою?',NULL,'["git fetch origin","git merge origin","git push origin","git init origin"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда завантажує об’єкти та посилання з origin без об’єднання з поточною гілкою? Правило, яке потрібно запам’ятати: git fetch origin Варіант «git fetch origin» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git merge origin» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git fetch origin». Варіант «git push origin» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git fetch origin». Варіант «git init origin» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git fetch origin».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда створює локальну копію віддаленого репозиторію?',NULL,'["git clone","git add","git revert","git branch"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда створює локальну копію віддаленого репозиторію? Правило, яке потрібно запам’ятати: git clone Варіант «git clone» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git add» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git clone». Варіант «git revert» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git clone». Варіант «git branch» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git clone».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда відправляє локальну гілку main до origin?',NULL,'["git push origin main","git fetch origin main","git switch origin main","git init origin main"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда відправляє локальну гілку main до origin? Правило, яке потрібно запам’ятати: git push origin main Варіант «git push origin main» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git fetch origin main» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git push origin main». Варіант «git switch origin main» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git push origin main». Варіант «git init origin main» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git push origin main».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git fetch origin?',NULL,'["Завантажує нові об’єкти з origin.","Оновлює відповідні remote-tracking посилання.","Об’єднує origin/main з локальною main.","Створює коміт у поточній гілці.","Відправляє локальні коміти до origin."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git fetch origin? Правило, яке потрібно запам’ятати: Завантажує нові об’єкти з origin.; Оновлює відповідні remote-tracking посилання. Варіант «Завантажує нові об’єкти з origin.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Оновлює відповідні remote-tracking посилання.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Об’єднує origin/main з локальною main.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Завантажує нові об’єкти з origin.; Оновлює відповідні remote-tracking посилання.». Варіант «Створює коміт у поточній гілці.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Завантажує нові об’єкти з origin.; Оновлює відповідні remote-tracking посилання.». Варіант «Відправляє локальні коміти до origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Завантажує нові об’єкти з origin.; Оновлює відповідні remote-tracking посилання.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про git pull правильні?',NULL,'["Команда спочатку отримує зміни з віддаленого репозиторію.","Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями.","Команда лише показує URL origin.","Команда видаляє локальні коміти перед завантаженням.","Команда створює новий віддалений репозиторій."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про git pull правильні? Правило, яке потрібно запам’ятати: Команда спочатку отримує зміни з віддаленого репозиторію.; Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями. Варіант «Команда спочатку отримує зміни з віддаленого репозиторію.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Команда лише показує URL origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда спочатку отримує зміни з віддаленого репозиторію.; Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями.». Варіант «Команда видаляє локальні коміти перед завантаженням.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда спочатку отримує зміни з віддаленого репозиторію.; Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями.». Варіант «Команда створює новий віддалений репозиторій.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда спочатку отримує зміни з віддаленого репозиторію.; Команда інтегрує отриману гілку в поточну гілку згідно з налаштуваннями.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git remote add upstream URL?',NULL,'["Додає віддалений репозиторій із назвою upstream.","Зберігає URL для наступних мережевих команд.","Одразу завантажує всі гілки upstream.","Перейменовує origin на upstream.","Перемикає поточну гілку на upstream."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git remote add upstream URL? Правило, яке потрібно запам’ятати: Додає віддалений репозиторій із назвою upstream.; Зберігає URL для наступних мережевих команд. Варіант «Додає віддалений репозиторій із назвою upstream.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зберігає URL для наступних мережевих команд.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Одразу завантажує всі гілки upstream.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Додає віддалений репозиторій із назвою upstream.; Зберігає URL для наступних мережевих команд.». Варіант «Перейменовує origin на upstream.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Додає віддалений репозиторій із назвою upstream.; Зберігає URL для наступних мережевих команд.». Варіант «Перемикає поточну гілку на upstream.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Додає віддалений репозиторій із назвою upstream.; Зберігає URL для наступних мережевих команд.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про remote-tracking гілку origin/main правильні?',NULL,'["Вона відображає відоме локальному Git положення main у origin.","Вона оновлюється під час відповідного fetch.","Новий локальний коміт пересуває її разом із main.","На неї потрібно перемикатися для кожного локального коміту.","Вона зберігається тільки у вебінтерфейсі GitHub."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про remote-tracking гілку origin/main правильні? Правило, яке потрібно запам’ятати: Вона відображає відоме локальному Git положення main у origin.; Вона оновлюється під час відповідного fetch. Варіант «Вона відображає відоме локальному Git положення main у origin.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Вона оновлюється під час відповідного fetch.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Новий локальний коміт пересуває її разом із main.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вона відображає відоме локальному Git положення main у origin.; Вона оновлюється під час відповідного fetch.». Варіант «На неї потрібно перемикатися для кожного локального коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вона відображає відоме локальному Git положення main у origin.; Вона оновлюється під час відповідного fetch.». Варіант «Вона зберігається тільки у вебінтерфейсі GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вона відображає відоме локальному Git положення main у origin.; Вона оновлюється під час відповідного fetch.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git push -u origin feature під час першої публікації гілки?',NULL,'["Відправляє локальну feature до origin.","Налаштовує upstream для локальної feature.","Об’єднує feature з main у origin.","Видаляє локальну feature після відправлення.","Завантажує всі чужі гілки до робочого дерева."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git push -u origin feature під час першої публікації гілки? Правило, яке потрібно запам’ятати: Відправляє локальну feature до origin.; Налаштовує upstream для локальної feature. Варіант «Відправляє локальну feature до origin.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Налаштовує upstream для локальної feature.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Об’єднує feature з main у origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відправляє локальну feature до origin.; Налаштовує upstream для локальної feature.». Варіант «Видаляє локальну feature після відправлення.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відправляє локальну feature до origin.; Налаштовує upstream для локальної feature.». Варіант «Завантажує всі чужі гілки до робочого дерева.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відправляє локальну feature до origin.; Налаштовує upstream для локальної feature.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що зміниться після виконання команд?','git remote add origin https://github.com/team/app.git
git remote -v','["З’явиться запис origin з указаними fetch і push URL.","Буде завантажено робоче дерево з GitHub.","Локальна гілка main буде відправлена на сервер.","HEAD перемкнеться на origin/main."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що зміниться після виконання команд? Правило, яке потрібно запам’ятати: З’явиться запис origin з указаними fetch і push URL. Варіант «З’явиться запис origin з указаними fetch і push URL.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Буде завантажено робоче дерево з GitHub.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «З’явиться запис origin з указаними fetch і push URL.». Варіант «Локальна гілка main буде відправлена на сервер.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «З’явиться запис origin з указаними fetch і push URL.». Варіант «HEAD перемкнеться на origin/main.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «З’явиться запис origin з указаними fetch і push URL.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який стан матимуть посилання після git fetch?','git switch main
git fetch origin
# В origin/main є новий коміт','["origin/main оновиться, а локальна main не буде об’єднана з ним.","Локальна main пересунеться на origin/main без merge.","origin/main буде видалено після завантаження.","Локальні зміни буде записано у віддалений коміт."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який стан матимуть посилання після git fetch? Правило, яке потрібно запам’ятати: origin/main оновиться, а локальна main не буде об’єднана з ним. Варіант «origin/main оновиться, а локальна main не буде об’єднана з ним.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Локальна main пересунеться на origin/main без merge.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «origin/main оновиться, а локальна main не буде об’єднана з ним.». Варіант «origin/main буде видалено після завантаження.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «origin/main оновиться, а локальна main не буде об’єднана з ним.». Варіант «Локальні зміни буде записано у віддалений коміт.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «origin/main оновиться, а локальна main не буде об’єднана з ним.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що зробить git pull у цьому сценарії?','git switch main
# main відстежує origin/main
git pull','["Отримає зміни origin/main та інтегрує їх у локальну main.","Відправить локальну main до origin.","Лише покаже різницю між двома гілками.","Створить новий репозиторій origin."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що зробить git pull у цьому сценарії? Правило, яке потрібно запам’ятати: Отримає зміни origin/main та інтегрує їх у локальну main. Варіант «Отримає зміни origin/main та інтегрує їх у локальну main.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Відправить локальну main до origin.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Отримає зміни origin/main та інтегрує їх у локальну main.». Варіант «Лише покаже різницю між двома гілками.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Отримає зміни origin/main та інтегрує їх у локальну main.». Варіант «Створить новий репозиторій origin.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Отримає зміни origin/main та інтегрує їх у локальну main.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде результат першої публікації feature?','git switch feature
git push -u origin feature','["Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою.","Гілку feature буде об’єднано з origin/main без окремого merge.","Локальну гілку feature буде перейменовано на гілку origin.","Усі наявні віддалені гілки origin буде видалено із сервера."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде результат першої публікації feature? Правило, яке потрібно запам’ятати: Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою. Варіант «Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Гілку feature буде об’єднано з origin/main без окремого merge.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою.». Варіант «Локальну гілку feature буде перейменовано на гілку origin.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою.». Варіант «Усі наявні віддалені гілки origin буде видалено із сервера.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Гілку feature буде відправлено до origin і пов’язано з upstream-гілкою.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які налаштування створить git clone для цього репозиторію?','git clone https://github.com/team/source.git
Set-Location source
git remote -v','["Створить локальний репозиторій і додасть source як origin.","Створить порожній каталог без історії.","Додасть source як upstream без робочого дерева.","Відправить локальну історію до source."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Які налаштування створить git clone для цього репозиторію? Правило, яке потрібно запам’ятати: Створить локальний репозиторій і додасть source як origin. Варіант «Створить локальний репозиторій і додасть source як origin.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Створить порожній каталог без історії.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Створить локальний репозиторій і додасть source як origin.». Варіант «Додасть source як upstream без робочого дерева.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Створить локальний репозиторій і додасть source як origin.». Варіант «Відправить локальну історію до source.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Створить локальний репозиторій і додасть source як origin.».' FROM topics WHERE slug='git-remotes' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Де в GitHub flow зазвичай виконують роботу над окремою зміною?',NULL,'["В окремій гілці","Безпосередньо в release","У файлі .gitignore","У списку тегів"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Де в GitHub flow зазвичай виконують роботу над окремою зміною? Правило, яке потрібно запам’ятати: В окремій гілці Варіант «В окремій гілці» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Безпосередньо в release» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «В окремій гілці». Варіант «У файлі .gitignore» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «В окремій гілці». Варіант «У списку тегів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «В окремій гілці».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Для чого створюють pull request?',NULL,'["Щоб запропонувати й обговорити зміни перед інтеграцією","Щоб видалити локальну копію репозиторію після розробки","Щоб установити іншу версію Git на комп’ютер автора","Щоб перейменувати обліковий запис учасника репозиторію"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Для чого створюють pull request? Правило, яке потрібно запам’ятати: Щоб запропонувати й обговорити зміни перед інтеграцією Варіант «Щоб запропонувати й обговорити зміни перед інтеграцією» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Щоб видалити локальну копію репозиторію після розробки» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб запропонувати й обговорити зміни перед інтеграцією». Варіант «Щоб установити іншу версію Git на комп’ютер автора» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб запропонувати й обговорити зміни перед інтеграцією». Варіант «Щоб перейменувати обліковий запис учасника репозиторію» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб запропонувати й обговорити зміни перед інтеграцією».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка дія переносить схвалені зміни pull request до цільової гілки?',NULL,'["Merge pull request","Close issue","Create fork","Add topic"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка дія переносить схвалені зміни pull request до цільової гілки? Правило, яке потрібно запам’ятати: Merge pull request Варіант «Merge pull request» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Close issue» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Merge pull request». Варіант «Create fork» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Merge pull request». Варіант «Add topic» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Merge pull request».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Для чого потрібен review pull request?',NULL,'["Для перевірки коду та обговорення змін","Для клонування репозиторію без історії","Для створення локального індексу","Для зміни адреси електронної пошти"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Для чого потрібен review pull request? Правило, яке потрібно запам’ятати: Для перевірки коду та обговорення змін Варіант «Для перевірки коду та обговорення змін» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Для клонування репозиторію без історії» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для перевірки коду та обговорення змін». Варіант «Для створення локального індексу» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для перевірки коду та обговорення змін». Варіант «Для зміни адреси електронної пошти» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Для перевірки коду та обговорення змін».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Коли доцільно відкрити draft pull request?',NULL,'["Коли зміни ще не готові до фінального review","Коли зміни вже потрібно негайно об’єднати без review","Коли роботу в гілці завершено й pull request уже merged","Коли потрібно закрити pull request без обговорення"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Коли доцільно відкрити draft pull request? Правило, яке потрібно запам’ятати: Коли зміни ще не готові до фінального review Варіант «Коли зміни ще не готові до фінального review» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коли зміни вже потрібно негайно об’єднати без review» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли зміни ще не готові до фінального review». Варіант «Коли роботу в гілці завершено й pull request уже merged» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли зміни ще не готові до фінального review». Варіант «Коли потрібно закрити pull request без обговорення» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли зміни ще не готові до фінального review».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два кроки належать до GitHub flow після створення гілки?',NULL,'["Потрібно додати коміти зі змінами.","Потрібно відкрити pull request для обговорення та перевірки.","Потрібно видалити цільову гілку.","Потрібно перетворити репозиторій на архів.","Потрібно очистити всю історію комітів."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два кроки належать до GitHub flow після створення гілки? Правило, яке потрібно запам’ятати: Потрібно додати коміти зі змінами.; Потрібно відкрити pull request для обговорення та перевірки. Варіант «Потрібно додати коміти зі змінами.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно відкрити pull request для обговорення та перевірки.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно видалити цільову гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати коміти зі змінами.; Потрібно відкрити pull request для обговорення та перевірки.». Варіант «Потрібно перетворити репозиторій на архів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати коміти зі змінами.; Потрібно відкрити pull request для обговорення та перевірки.». Варіант «Потрібно очистити всю історію комітів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати коміти зі змінами.; Потрібно відкрити pull request для обговорення та перевірки.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві можливості дає pull request до merge?',NULL,'["Команда може переглянути різницю між гілками.","Учасники можуть залишати review та коментарі.","GitHub видаляє вихідну гілку під час відкриття.","Pull request переписує локальну історію автора.","Pull request вимикає перевірки репозиторію."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві можливості дає pull request до merge? Правило, яке потрібно запам’ятати: Команда може переглянути різницю між гілками.; Учасники можуть залишати review та коментарі. Варіант «Команда може переглянути різницю між гілками.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Учасники можуть залишати review та коментарі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «GitHub видаляє вихідну гілку під час відкриття.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда може переглянути різницю між гілками.; Учасники можуть залишати review та коментарі.». Варіант «Pull request переписує локальну історію автора.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда може переглянути різницю між гілками.; Учасники можуть залишати review та коментарі.». Варіант «Pull request вимикає перевірки репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда може переглянути різницю між гілками.; Учасники можуть залишати review та коментарі.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві перевірки можуть бути умовами захисту цільової гілки?',NULL,'["Успішні status checks","Схвальні reviews","Наявність локального stash","Порожній файл .gitignore","Однакова назва всіх комітів"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві перевірки можуть бути умовами захисту цільової гілки? Правило, яке потрібно запам’ятати: Успішні status checks; Схвальні reviews Варіант «Успішні status checks» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Схвальні reviews» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Наявність локального stash» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Успішні status checks; Схвальні reviews». Варіант «Порожній файл .gitignore» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Успішні status checks; Схвальні reviews». Варіант «Однакова назва всіх комітів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Успішні status checks; Схвальні reviews».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії доречні після зауважень у review?',NULL,'["Потрібно внести виправлення у вихідну гілку.","Потрібно відправити нові коміти до тієї самої гілки pull request.","Потрібно створити новий репозиторій для кожного коментаря.","Потрібно видалити попередні reviews з історії Git.","Потрібно закрити цільову гілку."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії доречні після зауважень у review? Правило, яке потрібно запам’ятати: Потрібно внести виправлення у вихідну гілку.; Потрібно відправити нові коміти до тієї самої гілки pull request. Варіант «Потрібно внести виправлення у вихідну гілку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно відправити нові коміти до тієї самої гілки pull request.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно створити новий репозиторій для кожного коментаря.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно внести виправлення у вихідну гілку.; Потрібно відправити нові коміти до тієї самої гілки pull request.». Варіант «Потрібно видалити попередні reviews з історії Git.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно внести виправлення у вихідну гілку.; Потрібно відправити нові коміти до тієї самої гілки pull request.». Варіант «Потрібно закрити цільову гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно внести виправлення у вихідну гілку.; Потрібно відправити нові коміти до тієї самої гілки pull request.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії зазвичай завершують роботу з прийнятим pull request?',NULL,'["Зміни інтегрують у цільову гілку.","Вихідну гілку можна видалити після merge.","Цільовий репозиторій потрібно клонувати заново.","Усі issues репозиторію потрібно закрити.","Історію main потрібно очистити."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії зазвичай завершують роботу з прийнятим pull request? Правило, яке потрібно запам’ятати: Зміни інтегрують у цільову гілку.; Вихідну гілку можна видалити після merge. Варіант «Зміни інтегрують у цільову гілку.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Вихідну гілку можна видалити після merge.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Цільовий репозиторій потрібно клонувати заново.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни інтегрують у цільову гілку.; Вихідну гілку можна видалити після merge.». Варіант «Усі issues репозиторію потрібно закрити.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни інтегрують у цільову гілку.; Вихідну гілку можна видалити після merge.». Варіант «Історію main потрібно очистити.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Зміни інтегрують у цільову гілку.; Вихідну гілку можна видалити після merge.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два кроки правильно продовжують GitHub flow після публікації гілки зі змінами?',NULL,'["Відкрити pull request до потрібної цільової гілки.","Запросити review та дочекатися потрібних перевірок.","Видалити цільову гілку до review.","Переписати історію всіх учасників репозиторію.","Зробити репозиторій приватним перед кожним merge.","Створити release замість pull request."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два кроки правильно продовжують GitHub flow після публікації гілки зі змінами? Правило, яке потрібно запам’ятати: Відкрити pull request до потрібної цільової гілки.; Запросити review та дочекатися потрібних перевірок. Варіант «Відкрити pull request до потрібної цільової гілки.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Запросити review та дочекатися потрібних перевірок.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Видалити цільову гілку до review.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відкрити pull request до потрібної цільової гілки.; Запросити review та дочекатися потрібних перевірок.». Варіант «Переписати історію всіх учасників репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відкрити pull request до потрібної цільової гілки.; Запросити review та дочекатися потрібних перевірок.». Варіант «Зробити репозиторій приватним перед кожним merge.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відкрити pull request до потрібної цільової гілки.; Запросити review та дочекатися потрібних перевірок.». Варіант «Створити release замість pull request.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Відкрити pull request до потрібної цільової гілки.; Запросити review та дочекатися потрібних перевірок.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які дві властивості правильно описують draft pull request?',NULL,'["Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.","Перед фінальним merge його потрібно позначити готовим до review.","Він одразу інтегрує незавершені зміни в цільову гілку.","Він приховує diff від усіх учасників репозиторію до merge.","Він видаляє вихідну гілку після кожного нового push.","Він замінює локальний Git-репозиторій віддаленою копією."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві властивості правильно описують draft pull request? Правило, яке потрібно запам’ятати: Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.; Перед фінальним merge його потрібно позначити готовим до review. Варіант «Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Перед фінальним merge його потрібно позначити готовим до review.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Він одразу інтегрує незавершені зміни в цільову гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.; Перед фінальним merge його потрібно позначити готовим до review.». Варіант «Він приховує diff від усіх учасників репозиторію до merge.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.; Перед фінальним merge його потрібно позначити готовим до review.». Варіант «Він видаляє вихідну гілку після кожного нового push.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.; Перед фінальним merge його потрібно позначити готовим до review.». Варіант «Він замінює локальний Git-репозиторій віддаленою копією.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він показує незавершену роботу та дає змогу отримати ранній зворотний зв’язок.; Перед фінальним merge його потрібно позначити готовим до review.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які дві умови можуть блокувати merge у захищену гілку?',NULL,'["Обов’язкова перевірка ще не завершилася успішно.","Не отримано потрібну кількість схвальних reviews.","Автор не видалив локальний stash.","Назва локального каталогу не збігається з назвою репозиторію.","У репозиторії є файл README.","Вихідна гілка містить більше одного коміту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві умови можуть блокувати merge у захищену гілку? Правило, яке потрібно запам’ятати: Обов’язкова перевірка ще не завершилася успішно.; Не отримано потрібну кількість схвальних reviews. Варіант «Обов’язкова перевірка ще не завершилася успішно.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Не отримано потрібну кількість схвальних reviews.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Автор не видалив локальний stash.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Обов’язкова перевірка ще не завершилася успішно.; Не отримано потрібну кількість схвальних reviews.». Варіант «Назва локального каталогу не збігається з назвою репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Обов’язкова перевірка ще не завершилася успішно.; Не отримано потрібну кількість схвальних reviews.». Варіант «У репозиторії є файл README.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Обов’язкова перевірка ще не завершилася успішно.; Не отримано потрібну кількість схвальних reviews.». Варіант «Вихідна гілка містить більше одного коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Обов’язкова перевірка ще не завершилася успішно.; Не отримано потрібну кількість схвальних reviews.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які дві дії оновлять відкритий pull request після виправлення зауважень?',NULL,'["Створити новий коміт у його вихідній гілці.","Відправити оновлену вихідну гілку до GitHub.","Створити інший репозиторій із тим самим ім’ям.","Видалити цільову гілку та відкрити її знову.","Перетворити pull request на issue.","Очистити історію всього репозиторію."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії оновлять відкритий pull request після виправлення зауважень? Правило, яке потрібно запам’ятати: Створити новий коміт у його вихідній гілці.; Відправити оновлену вихідну гілку до GitHub. Варіант «Створити новий коміт у його вихідній гілці.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Відправити оновлену вихідну гілку до GitHub.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Створити інший репозиторій із тим самим ім’ям.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створити новий коміт у його вихідній гілці.; Відправити оновлену вихідну гілку до GitHub.». Варіант «Видалити цільову гілку та відкрити її знову.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створити новий коміт у його вихідній гілці.; Відправити оновлену вихідну гілку до GitHub.». Варіант «Перетворити pull request на issue.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створити новий коміт у його вихідній гілці.; Відправити оновлену вихідну гілку до GitHub.». Варіант «Очистити історію всього репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створити новий коміт у його вихідній гілці.; Відправити оновлену вихідну гілку до GitHub.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які дві дії зменшують ризик інтеграції несправних змін через pull request?',NULL,'["Перегляд змін іншими учасниками.","Запуск автоматизованих перевірок до merge.","Видалення опису pull request.","Об’єднання до завершення тестів.","Вимкнення захисту цільової гілки.","Приховування diff від reviewers."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії зменшують ризик інтеграції несправних змін через pull request? Правило, яке потрібно запам’ятати: Перегляд змін іншими учасниками.; Запуск автоматизованих перевірок до merge. Варіант «Перегляд змін іншими учасниками.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Запуск автоматизованих перевірок до merge.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Видалення опису pull request.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Перегляд змін іншими учасниками.; Запуск автоматизованих перевірок до merge.». Варіант «Об’єднання до завершення тестів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Перегляд змін іншими учасниками.; Запуск автоматизованих перевірок до merge.». Варіант «Вимкнення захисту цільової гілки.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Перегляд змін іншими учасниками.; Запуск автоматизованих перевірок до merge.». Варіант «Приховування diff від reviewers.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Перегляд змін іншими учасниками.; Запуск автоматизованих перевірок до merge.».' FROM topics WHERE slug='github-workflow' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Коли Git повідомляє про merge conflict?',NULL,'["Коли не може самостійно узгодити зміни","Коли робоче дерево не містить файлів","Коли в репозиторії одна гілка","Коли коміт має повідомлення"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Коли Git повідомляє про merge conflict? Правило, яке потрібно запам’ятати: Коли не може самостійно узгодити зміни Варіант «Коли не може самостійно узгодити зміни» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коли робоче дерево не містить файлів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли не може самостійно узгодити зміни». Варіант «Коли в репозиторії одна гілка» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли не може самостійно узгодити зміни». Варіант «Коли коміт має повідомлення» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Коли не може самостійно узгодити зміни».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує файли з невирішеними конфліктами?',NULL,'["git status","git init","git clone","git remote"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда показує файли з невирішеними конфліктами? Правило, яке потрібно запам’ятати: git status Варіант «git status» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git init» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status». Варіант «git clone» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status». Варіант «git remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git status».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Якими рядками Git позначає початок і межу конфліктних версій у файлі?',NULL,'["<<<<<<<, ======= та >>>>>>>","/*, *, */","BEGIN, MIDDLE та END","{{, || та }}"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Якими рядками Git позначає початок і межу конфліктних версій у файлі? Правило, яке потрібно запам’ятати: <<<<<<<, ======= та >>>>>>> Варіант «<<<<<<<, ======= та >>>>>>>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «/*, *, */» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «<<<<<<<, ======= та >>>>>>>». Варіант «BEGIN, MIDDLE та END» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «<<<<<<<, ======= та >>>>>>>». Варіант «{{, || та }}» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «<<<<<<<, ======= та >>>>>>>».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда позначає виправлений app.js як розв’язаний?',NULL,'["git add app.js","git log app.js","git init app.js","git fetch app.js"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда позначає виправлений app.js як розв’язаний? Правило, яке потрібно запам’ятати: git add app.js Варіант «git add app.js» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git log app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js». Варіант «git init app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js». Варіант «git fetch app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git add app.js».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда скасовує незавершене об’єднання та намагається повернути попередній стан?',NULL,'["git merge --abort","git merge --continue","git branch --delete","git remote --remove"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда скасовує незавершене об’єднання та намагається повернути попередній стан? Правило, яке потрібно запам’ятати: git merge --abort Варіант «git merge --abort» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git merge --continue» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge --abort». Варіант «git branch --delete» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge --abort». Варіант «git remote --remove» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git merge --abort».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві умови можуть спричинити конфлікт під час merge?',NULL,'["Гілки по-різному змінили ту саму частину файлу.","В одній гілці файл видалено, а в іншій змінено.","Гілки додали різні файли з різними назвами.","У репозиторії є віддалений origin.","Повідомлення комітів написані різними мовами."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві умови можуть спричинити конфлікт під час merge? Правило, яке потрібно запам’ятати: Гілки по-різному змінили ту саму частину файлу.; В одній гілці файл видалено, а в іншій змінено. Варіант «Гілки по-різному змінили ту саму частину файлу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «В одній гілці файл видалено, а в іншій змінено.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Гілки додали різні файли з різними назвами.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілки по-різному змінили ту саму частину файлу.; В одній гілці файл видалено, а в іншій змінено.». Варіант «У репозиторії є віддалений origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілки по-різному змінили ту саму частину файлу.; В одній гілці файл видалено, а в іншій змінено.». Варіант «Повідомлення комітів написані різними мовами.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Гілки по-різному змінили ту саму частину файлу.; В одній гілці файл видалено, а в іншій змінено.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії потрібні після ручного виправлення конфліктного файлу?',NULL,'["Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.","Потрібно виконати git add для виправленого файлу.","Потрібно повторно ініціалізувати репозиторій командою git init.","Потрібно видалити обидві гілки, які брали участь у merge.","Потрібно замінити URL віддаленого репозиторію origin."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії потрібні після ручного виправлення конфліктного файлу? Правило, яке потрібно запам’ятати: Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.; Потрібно виконати git add для виправленого файлу. Варіант «Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно виконати git add для виправленого файлу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно повторно ініціалізувати репозиторій командою git init.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.; Потрібно виконати git add для виправленого файлу.». Варіант «Потрібно видалити обидві гілки, які брали участь у merge.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.; Потрібно виконати git add для виправленого файлу.». Варіант «Потрібно замінити URL віддаленого репозиторію origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно прибрати конфліктні маркери та зберегти узгоджений вміст.; Потрібно виконати git add для виправленого файлу.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві частини показують маркери конфлікту?',NULL,'["Вміст поточної сторони об’єднання","Вміст іншої сторони об’єднання","Список усіх віддалених репозиторіїв","Повідомлення майбутнього коміту","Налаштування користувача Git"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві частини показують маркери конфлікту? Правило, яке потрібно запам’ятати: Вміст поточної сторони об’єднання; Вміст іншої сторони об’єднання Варіант «Вміст поточної сторони об’єднання» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Вміст іншої сторони об’єднання» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Список усіх віддалених репозиторіїв» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вміст поточної сторони об’єднання; Вміст іншої сторони об’єднання». Варіант «Повідомлення майбутнього коміту» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вміст поточної сторони об’єднання; Вміст іншої сторони об’єднання». Варіант «Налаштування користувача Git» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Вміст поточної сторони об’єднання; Вміст іншої сторони об’єднання».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві команди допомагають завершити або скасувати конфліктний merge?',NULL,'["git commit завершує merge після підготовки виправлень.","git merge --abort скасовує незавершений merge.","git clone завершує локальний merge.","git remote -v вибирає конфліктну версію.","git init скасовує один файл конфлікту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві команди допомагають завершити або скасувати конфліктний merge? Правило, яке потрібно запам’ятати: git commit завершує merge після підготовки виправлень.; git merge --abort скасовує незавершений merge. Варіант «git commit завершує merge після підготовки виправлень.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git merge --abort скасовує незавершений merge.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git clone завершує локальний merge.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit завершує merge після підготовки виправлень.; git merge --abort скасовує незавершений merge.». Варіант «git remote -v вибирає конфліктну версію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit завершує merge після підготовки виправлень.; git merge --abort скасовує незавершений merge.». Варіант «git init скасовує один файл конфлікту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit завершує merge після підготовки виправлень.; git merge --abort скасовує незавершений merge.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про стан unmerged paths правильні?',NULL,'["Git очікує ручного розв’язання відповідних файлів.","Після виправлення файл потрібно додати до індексу.","Конфлікт уже записано як звичайний коміт.","Git відправив конфліктні файли до origin.","Робоче дерево не містить конфліктних версій."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про стан unmerged paths правильні? Правило, яке потрібно запам’ятати: Git очікує ручного розв’язання відповідних файлів.; Після виправлення файл потрібно додати до індексу. Варіант «Git очікує ручного розв’язання відповідних файлів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Після виправлення файл потрібно додати до індексу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Конфлікт уже записано як звичайний коміт.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Git очікує ручного розв’язання відповідних файлів.; Після виправлення файл потрібно додати до індексу.». Варіант «Git відправив конфліктні файли до origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Git очікує ручного розв’язання відповідних файлів.; Після виправлення файл потрібно додати до індексу.». Варіант «Робоче дерево не містить конфліктних версій.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Git очікує ручного розв’язання відповідних файлів.; Після виправлення файл потрібно додати до індексу.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде результат merge у цьому сценарії?','# main: title.txt містить "Каталог"
# feature: той самий рядок змінено на "Магазин"
git switch main
git merge feature','["Git зупинить merge через конфлікт у title.txt.","Git вибере версію feature без повідомлення.","Git об’єднає два рядки в алфавітному порядку.","Git видалить title.txt."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде результат merge у цьому сценарії? Правило, яке потрібно запам’ятати: Git зупинить merge через конфлікт у title.txt. Варіант «Git зупинить merge через конфлікт у title.txt.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Git вибере версію feature без повідомлення.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git зупинить merge через конфлікт у title.txt.». Варіант «Git об’єднає два рядки в алфавітному порядку.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git зупинить merge через конфлікт у title.txt.». Варіант «Git видалить title.txt.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git зупинить merge через конфлікт у title.txt.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який стан покаже Git після цих дій?','# app.js мав merge conflict
# Маркери видалено, потрібний код збережено
git add app.js
git status','["Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом.","Merge уже завершено без створення нового коміту.","Файл app.js усе ще відображається серед невирішених шляхів.","Гілку feature видалено після додавання виправленого файлу."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який стан покаже Git після цих дій? Правило, яке потрібно запам’ятати: Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом. Варіант «Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Merge уже завершено без створення нового коміту.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом.». Варіант «Файл app.js усе ще відображається серед невирішених шляхів.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом.». Варіант «Гілку feature видалено після додавання виправленого файлу.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Конфлікт позначено розв’язаним, але merge ще потрібно завершити комітом.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що зробить остання команда?','git switch main
git merge feature
# Git повідомив про конфлікт
git merge --abort','["Скасує незавершений merge та спробує відновити стан до нього.","Створить merge-коміт із поточними маркерами.","Видалить гілку feature з origin.","Продовжить merge, вибравши поточну версію."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що зробить остання команда? Правило, яке потрібно запам’ятати: Скасує незавершений merge та спробує відновити стан до нього. Варіант «Скасує незавершений merge та спробує відновити стан до нього.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Створить merge-коміт із поточними маркерами.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Скасує незавершений merge та спробує відновити стан до нього.». Варіант «Видалить гілку feature з origin.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Скасує незавершений merge та спробує відновити стан до нього.». Варіант «Продовжить merge, вибравши поточну версію.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Скасує незавершений merge та спробує відновити стан до нього.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде результат об’єднання незалежних змін?','# main змінює header.css
# feature змінює footer.css
git switch main
git merge feature','["Git об’єднає зміни без текстового конфлікту між цими файлами.","Git створить текстовий конфлікт лише через різні назви файлів.","Git відкине зміну footer.css і залишить тільки зміну header.css.","Git видалить обидва змінені файли під час завершення merge."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде результат об’єднання незалежних змін? Правило, яке потрібно запам’ятати: Git об’єднає зміни без текстового конфлікту між цими файлами. Варіант «Git об’єднає зміни без текстового конфлікту між цими файлами.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Git створить текстовий конфлікт лише через різні назви файлів.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git об’єднає зміни без текстового конфлікту між цими файлами.». Варіант «Git відкине зміну footer.css і залишить тільки зміну header.css.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git об’єднає зміни без текстового конфлікту між цими файлами.». Варіант «Git видалить обидва змінені файли під час завершення merge.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git об’єднає зміни без текстового конфлікту між цими файлами.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що потрібно зробити з цим фрагментом перед завершенням merge?','  <<<<<<< HEAD
  Заголовок каталогу
  =======
  Заголовок магазину
  >>>>>>> feature','["Вибрати або поєднати потрібний текст і видалити всі маркери.","Залишити маркери у файлі як обов’язковий синтаксис Git.","Перейменувати конфліктний файл на службову назву MERGE_HEAD.","Замінити маркери на шаблони виключення у файлі .gitignore."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що потрібно зробити з цим фрагментом перед завершенням merge? Правило, яке потрібно запам’ятати: Вибрати або поєднати потрібний текст і видалити всі маркери. Варіант «Вибрати або поєднати потрібний текст і видалити всі маркери.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Залишити маркери у файлі як обов’язковий синтаксис Git.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Вибрати або поєднати потрібний текст і видалити всі маркери.». Варіант «Перейменувати конфліктний файл на службову назву MERGE_HEAD.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Вибрати або поєднати потрібний текст і видалити всі маркери.». Варіант «Замінити маркери на шаблони виключення у файлі .gitignore.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Вибрати або поєднати потрібний текст і видалити всі маркери.».' FROM topics WHERE slug='merge-conflicts' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда відкидає непідготовлені зміни у файлі app.js?',NULL,'["git restore app.js","git add app.js","git log app.js","git push app.js"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда відкидає непідготовлені зміни у файлі app.js? Правило, яке потрібно запам’ятати: git restore app.js Варіант «git restore app.js» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git add app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore app.js». Варіант «git log app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore app.js». Варіант «git push app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore app.js».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда прибирає app.js з індексу, але залишає зміни в робочому дереві?',NULL,'["git restore --staged app.js","git restore app.js","git clean app.js","git commit app.js"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда прибирає app.js з індексу, але залишає зміни в робочому дереві? Правило, яке потрібно запам’ятати: git restore --staged app.js Варіант «git restore --staged app.js» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git restore app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore --staged app.js». Варіант «git clean app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore --staged app.js». Варіант «git commit app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git restore --staged app.js».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда створює новий коміт, що скасовує зміни вказаного коміту?',NULL,'["git revert <commit>","git init <commit>","git fetch <commit>","git branch <commit>"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда створює новий коміт, що скасовує зміни вказаного коміту? Правило, яке потрібно запам’ятати: git revert <commit> Варіант «git revert <commit>» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git init <commit>» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git revert <commit>». Варіант «git fetch <commit>» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git revert <commit>». Варіант «git branch <commit>» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git revert <commit>».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який параметр дає змогу замінити останній коміт новим?',NULL,'["git commit --amend","git commit --abort","git commit --staged","git commit --remote"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який параметр дає змогу замінити останній коміт новим? Правило, яке потрібно запам’ятати: git commit --amend Варіант «git commit --amend» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git commit --abort» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit --amend». Варіант «git commit --staged» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit --amend». Варіант «git commit --remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git commit --amend».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда показує журнал змін положення HEAD і локальних посилань?',NULL,'["git reflog","git status","git remote","git ignore"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда показує журнал змін положення HEAD і локальних посилань? Правило, яке потрібно запам’ятати: git reflog Варіант «git reflog» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git status» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git reflog». Варіант «git remote» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git reflog». Варіант «git ignore» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git reflog».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git restore --staged app.js?',NULL,'["Прибирає зміни app.js з індексу.","Зберігає ці зміни в робочому дереві.","Видаляє app.js з файлової системи.","Створює коміт скасування.","Пересуває поточну гілку на попередній коміт."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git restore --staged app.js? Правило, яке потрібно запам’ятати: Прибирає зміни app.js з індексу.; Зберігає ці зміни в робочому дереві. Варіант «Прибирає зміни app.js з індексу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зберігає ці зміни в робочому дереві.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Видаляє app.js з файлової системи.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Прибирає зміни app.js з індексу.; Зберігає ці зміни в робочому дереві.». Варіант «Створює коміт скасування.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Прибирає зміни app.js з індексу.; Зберігає ці зміни в робочому дереві.». Варіант «Пересуває поточну гілку на попередній коміт.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Прибирає зміни app.js з індексу.; Зберігає ці зміни в робочому дереві.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про git revert правильні?',NULL,'["Команда створює новий коміт із зворотними змінами.","Наявна історія попередніх комітів зберігається.","Команда пересуває гілку назад без нового коміту.","Команда видаляє вказаний коміт з усіх копій репозиторію.","Команда працює лише з непідготовленими файлами."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про git revert правильні? Правило, яке потрібно запам’ятати: Команда створює новий коміт із зворотними змінами.; Наявна історія попередніх комітів зберігається. Варіант «Команда створює новий коміт із зворотними змінами.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Наявна історія попередніх комітів зберігається.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Команда пересуває гілку назад без нового коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда створює новий коміт із зворотними змінами.; Наявна історія попередніх комітів зберігається.». Варіант «Команда видаляє вказаний коміт з усіх копій репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда створює новий коміт із зворотними змінами.; Наявна історія попередніх комітів зберігається.». Варіант «Команда працює лише з непідготовленими файлами.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Команда створює новий коміт із зворотними змінами.; Наявна історія попередніх комітів зберігається.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два наслідки має git reset --soft HEAD~1?',NULL,'["Поточна гілка пересувається на батьківський коміт.","Зміни скасованого коміту залишаються підготовленими в індексі.","Робочі файли повертаються до батьківського коміту.","Створюється новий коміт скасування.","Віддалена гілка пересувається разом із локальною."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два наслідки має git reset --soft HEAD~1? Правило, яке потрібно запам’ятати: Поточна гілка пересувається на батьківський коміт.; Зміни скасованого коміту залишаються підготовленими в індексі. Варіант «Поточна гілка пересувається на батьківський коміт.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зміни скасованого коміту залишаються підготовленими в індексі.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Робочі файли повертаються до батьківського коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка пересувається на батьківський коміт.; Зміни скасованого коміту залишаються підготовленими в індексі.». Варіант «Створюється новий коміт скасування.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка пересувається на батьківський коміт.; Зміни скасованого коміту залишаються підготовленими в індексі.». Варіант «Віддалена гілка пересувається разом із локальною.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Поточна гілка пересувається на батьківський коміт.; Зміни скасованого коміту залишаються підготовленими в індексі.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує git commit --amend?',NULL,'["Створює новий коміт замість поточного останнього коміту.","Може включити підготовлені виправлення до нового останнього коміту.","Змінює повідомлення кожного попереднього коміту в поточній гілці.","Створює віддалену резервну гілку для попередньої версії коміту.","Скасовує незавершений merge і відновлює попередній стан."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує git commit --amend? Правило, яке потрібно запам’ятати: Створює новий коміт замість поточного останнього коміту.; Може включити підготовлені виправлення до нового останнього коміту. Варіант «Створює новий коміт замість поточного останнього коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Може включити підготовлені виправлення до нового останнього коміту.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Змінює повідомлення кожного попереднього коміту в поточній гілці.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює новий коміт замість поточного останнього коміту.; Може включити підготовлені виправлення до нового останнього коміту.». Варіант «Створює віддалену резервну гілку для попередньої версії коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює новий коміт замість поточного останнього коміту.; Може включити підготовлені виправлення до нового останнього коміту.». Варіант «Скасовує незавершений merge і відновлює попередній стан.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює новий коміт замість поточного останнього коміту.; Може включити підготовлені виправлення до нового останнього коміту.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два випадки допомагає дослідити git reflog?',NULL,'["Пошук попереднього положення HEAD після reset.","Пошук локального коміту після випадкового перемикання посилання.","Перегляд pull request без доступу до GitHub.","Пошук правил у глобальному .gitignore.","Порівняння швидкості двох віддалених серверів."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два випадки допомагає дослідити git reflog? Правило, яке потрібно запам’ятати: Пошук попереднього положення HEAD після reset.; Пошук локального коміту після випадкового перемикання посилання. Варіант «Пошук попереднього положення HEAD після reset.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Пошук локального коміту після випадкового перемикання посилання.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Перегляд pull request без доступу до GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Пошук попереднього положення HEAD після reset.; Пошук локального коміту після випадкового перемикання посилання.». Варіант «Пошук правил у глобальному .gitignore.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Пошук попереднього положення HEAD після reset.; Пошук локального коміту після випадкового перемикання посилання.». Варіант «Порівняння швидкості двох віддалених серверів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Пошук попереднього положення HEAD після reset.; Пошук локального коміту після випадкового перемикання посилання.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який стан матиме app.js після виконання команди?','# app.js змінено після останнього git add
git restore app.js
git status','["Непідготовлені зміни буде замінено версією з індексу.","Зміни буде додано до індексу.","Буде створено коміт скасування.","Поточна гілка пересунеться на попередній коміт."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який стан матиме app.js після виконання команди? Правило, яке потрібно запам’ятати: Непідготовлені зміни буде замінено версією з індексу. Варіант «Непідготовлені зміни буде замінено версією з індексу.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Зміни буде додано до індексу.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Непідготовлені зміни буде замінено версією з індексу.». Варіант «Буде створено коміт скасування.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Непідготовлені зміни буде замінено версією з індексу.». Варіант «Поточна гілка пересунеться на попередній коміт.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Непідготовлені зміни буде замінено версією з індексу.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Де залишаться зміни app.js після виконання команди?','# Зміни app.js підготовлено в індексі
git restore --staged app.js
git status','["У робочому дереві як непідготовлені зміни.","Лише в новому коміті.","У віддаленій гілці origin/main.","Зміни буде видалено з робочого дерева."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Де залишаться зміни app.js після виконання команди? Правило, яке потрібно запам’ятати: У робочому дереві як непідготовлені зміни. Варіант «У робочому дереві як непідготовлені зміни.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Лише в новому коміті.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «У робочому дереві як непідготовлені зміни.». Варіант «У віддаленій гілці origin/main.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «У робочому дереві як непідготовлені зміни.». Варіант «Зміни буде видалено з робочого дерева.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «У робочому дереві як непідготовлені зміни.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який стан матимуть HEAD, індекс і робоче дерево?','# Історія: A-B, HEAD указує на B
git reset --soft HEAD~1
git status','["HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві.","HEAD залишиться на B, а індекс очиститься.","HEAD пересунеться на A, а зміни B буде видалено з індексу й робочого дерева.","Буде створено коміт C, який скасовує B."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який стан матимуть HEAD, індекс і робоче дерево? Правило, яке потрібно запам’ятати: HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві. Варіант «HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «HEAD залишиться на B, а індекс очиститься.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві.». Варіант «HEAD пересунеться на A, а зміни B буде видалено з індексу й робочого дерева.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві.». Варіант «Буде створено коміт C, який скасовує B.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а зміни B залишаться підготовленими та в робочому дереві.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Який результат матиме ця команда?','# Історія: A-B, HEAD указує на B
git reset --hard HEAD~1
git status','["HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A.","HEAD залишиться на B, а зміни B стануть непідготовленими.","Буде створено коміт C зі зворотними змінами.","Локальна main та origin/main пересунуться на A."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який результат матиме ця команда? Правило, яке потрібно запам’ятати: HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A. Варіант «HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «HEAD залишиться на B, а зміни B стануть непідготовленими.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A.». Варіант «Буде створено коміт C зі зворотними змінами.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A.». Варіант «Локальна main та origin/main пересунуться на A.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «HEAD пересунеться на A, а індекс і робоче дерево відповідатимуть A.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Як зміниться історія після виконання команди?','# Історія main: A-B, ідентифікатор B — abc1234
git revert abc1234
# Конфліктів немає','["Після B з’явиться новий коміт, що скасовує зміни B.","Коміт B буде видалено, а main пересунеться на A.","Коміт B отримає інший ідентифікатор без нового коміту.","Віддалену гілку буде видалено."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Як зміниться історія після виконання команди? Правило, яке потрібно запам’ятати: Після B з’явиться новий коміт, що скасовує зміни B. Варіант «Після B з’явиться новий коміт, що скасовує зміни B.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Коміт B буде видалено, а main пересунеться на A.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Після B з’явиться новий коміт, що скасовує зміни B.». Варіант «Коміт B отримає інший ідентифікатор без нового коміту.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Після B з’явиться новий коміт, що скасовує зміни B.». Варіант «Віддалену гілку буде видалено.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Після B з’явиться новий коміт, що скасовує зміни B.».' FROM topics WHERE slug='git-undo-history' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Для чого використовують файл .gitignore?',NULL,'["Щоб Git не пропонував додавати відповідні невідстежувані файли","Щоб видаляти вибрані коміти з історії поточної гілки","Щоб приховувати віддалені гілки у виведенні git branch","Щоб змінювати автора майбутніх комітів у репозиторії"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Для чого використовують файл .gitignore? Правило, яке потрібно запам’ятати: Щоб Git не пропонував додавати відповідні невідстежувані файли Варіант «Щоб Git не пропонував додавати відповідні невідстежувані файли» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Щоб видаляти вибрані коміти з історії поточної гілки» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб Git не пропонував додавати відповідні невідстежувані файли». Варіант «Щоб приховувати віддалені гілки у виведенні git branch» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб Git не пропонував додавати відповідні невідстежувані файли». Варіант «Щоб змінювати автора майбутніх комітів у репозиторії» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Щоб Git не пропонував додавати відповідні невідстежувані файли».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який шаблон ігнорує файли з розширенням .log?',NULL,'["*.log","log.*","/log/","!*.log"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який шаблон ігнорує файли з розширенням .log? Правило, яке потрібно запам’ятати: *.log Варіант «*.log» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «log.*» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «*.log». Варіант «/log/» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «*.log». Варіант «!*.log» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «*.log».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який запис ігнорує каталог dist та його вміст?',NULL,'["dist/","!dist/","dist.txt","# dist/"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який запис ігнорує каталог dist та його вміст? Правило, яке потрібно запам’ятати: dist/ Варіант «dist/» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «!dist/» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «dist/». Варіант «dist.txt» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «dist/». Варіант «# dist/» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «dist/».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що означає знак ! на початку шаблону .gitignore?',NULL,'["Повторно включає шлях, виключений попереднім шаблоном","Позначає коментар","Ігнорує всі каталоги","Застосовує шаблон лише до комітів"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що означає знак ! на початку шаблону .gitignore? Правило, яке потрібно запам’ятати: Повторно включає шлях, виключений попереднім шаблоном Варіант «Повторно включає шлях, виключений попереднім шаблоном» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Позначає коментар» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Повторно включає шлях, виключений попереднім шаблоном». Варіант «Ігнорує всі каталоги» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Повторно включає шлях, виключений попереднім шаблоном». Варіант «Застосовує шаблон лише до комітів» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Повторно включає шлях, виключений попереднім шаблоном».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Як .gitignore впливає на файл, який Git уже відстежує?',NULL,'["Файл продовжує відстежуватися","Файл видаляється з історії","Файл стає віддаленою гілкою","Файл переміщується до .git"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Як .gitignore впливає на файл, який Git уже відстежує? Правило, яке потрібно запам’ятати: Файл продовжує відстежуватися Варіант «Файл продовжує відстежуватися» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Файл видаляється з історії» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Файл продовжує відстежуватися». Варіант «Файл стає віддаленою гілкою» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Файл продовжує відстежуватися». Варіант «Файл переміщується до .git» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Файл продовжує відстежуватися».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два шляхи ігнорує шаблон *.tmp?',NULL,'["cache.tmp у каталозі з відповідним .gitignore","logs/error.tmp у підкаталозі","cache.txt у тому самому каталозі","tmp/cache.js","файл із назвою temp без розширення"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два шляхи ігнорує шаблон *.tmp? Правило, яке потрібно запам’ятати: cache.tmp у каталозі з відповідним .gitignore; logs/error.tmp у підкаталозі Варіант «cache.tmp у каталозі з відповідним .gitignore» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «logs/error.tmp у підкаталозі» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «cache.txt у тому самому каталозі» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «cache.tmp у каталозі з відповідним .gitignore; logs/error.tmp у підкаталозі». Варіант «tmp/cache.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «cache.tmp у каталозі з відповідним .gitignore; logs/error.tmp у підкаталозі». Варіант «файл із назвою temp без розширення» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «cache.tmp у каталозі з відповідним .gitignore; logs/error.tmp у підкаталозі».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про записи .gitignore правильні?',NULL,'["Рядок, що починається з #, використовується як коментар.","Кінцевий символ / обмежує шаблон каталогами.","Знак ! позначає коментар до шаблону.","Порожній рядок ігнорує всі файли.","Кожний шаблон застосовується лише до одного коміту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про записи .gitignore правильні? Правило, яке потрібно запам’ятати: Рядок, що починається з #, використовується як коментар.; Кінцевий символ / обмежує шаблон каталогами. Варіант «Рядок, що починається з #, використовується як коментар.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Кінцевий символ / обмежує шаблон каталогами.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Знак ! позначає коментар до шаблону.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Рядок, що починається з #, використовується як коментар.; Кінцевий символ / обмежує шаблон каталогами.». Варіант «Порожній рядок ігнорує всі файли.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Рядок, що починається з #, використовується як коментар.; Кінцевий символ / обмежує шаблон каталогами.». Варіант «Кожний шаблон застосовується лише до одного коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Рядок, що починається з #, використовується як коментар.; Кінцевий символ / обмежує шаблон каталогами.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії потрібні, щоб припинити відстежувати config.local, але залишити файл на диску?',NULL,'["Потрібно додати config.local до .gitignore.","Потрібно виконати git rm --cached config.local і зафіксувати зміну.","Потрібно виконати git restore config.local.","Потрібно видалити каталог .git.","Потрібно змінити URL origin."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії потрібні, щоб припинити відстежувати config.local, але залишити файл на диску? Правило, яке потрібно запам’ятати: Потрібно додати config.local до .gitignore.; Потрібно виконати git rm --cached config.local і зафіксувати зміну. Варіант «Потрібно додати config.local до .gitignore.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно виконати git rm --cached config.local і зафіксувати зміну.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно виконати git restore config.local.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати config.local до .gitignore.; Потрібно виконати git rm --cached config.local і зафіксувати зміну.». Варіант «Потрібно видалити каталог .git.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати config.local до .gitignore.; Потрібно виконати git rm --cached config.local і зафіксувати зміну.». Варіант «Потрібно змінити URL origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно додати config.local до .gitignore.; Потрібно виконати git rm --cached config.local і зафіксувати зміну.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два файли будуть проігноровані шаблонами build/ і *.log?',NULL,'["build/app.js","debug.log","src/app.js","logs/readme.txt","build-notes.md"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два файли будуть проігноровані шаблонами build/ і *.log? Правило, яке потрібно запам’ятати: build/app.js; debug.log Варіант «build/app.js» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «debug.log» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «src/app.js» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «build/app.js; debug.log». Варіант «logs/readme.txt» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «build/app.js; debug.log». Варіант «build-notes.md» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «build/app.js; debug.log».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про область дії вкладеного .gitignore правильні?',NULL,'["Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.","Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня.","Його шаблони змінюють правила для файлів у батьківських каталогах.","Його шаблони починають діяти лише після виконання git push.","Його шаблони видаляють відповідні файли з попередніх комітів."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про область дії вкладеного .gitignore правильні? Правило, яке потрібно запам’ятати: Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.; Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня. Варіант «Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Його шаблони змінюють правила для файлів у батьківських каталогах.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.; Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня.». Варіант «Його шаблони починають діяти лише після виконання git push.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.; Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня.». Варіант «Його шаблони видаляють відповідні файли з попередніх комітів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Його шаблони застосовуються до каталогу цього файла та нижчих рівнів.; Для доступного шляху шаблон нижчого рівня може перевизначити шаблон вищого рівня.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження описують вплив .gitignore на відстеження файлів?',NULL,'["Шаблони визначають невідстежувані файли, які Git не має додавати.","Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.","Шаблон видаляє відповідні файли з усіх попередніх комітів.","Шаблон забороняє створювати відповідні файли на диску.","Файл .gitignore змінює дозволи файлової системи.","Шаблони діють тільки на віддаленому сервері."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження описують вплив .gitignore на відстеження файлів? Правило, яке потрібно запам’ятати: Шаблони визначають невідстежувані файли, які Git не має додавати.; Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон. Варіант «Шаблони визначають невідстежувані файли, які Git не має додавати.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Шаблон видаляє відповідні файли з усіх попередніх комітів.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Шаблони визначають невідстежувані файли, які Git не має додавати.; Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.». Варіант «Шаблон забороняє створювати відповідні файли на диску.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Шаблони визначають невідстежувані файли, які Git не має додавати.; Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.». Варіант «Файл .gitignore змінює дозволи файлової системи.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Шаблони визначають невідстежувані файли, які Git не має додавати.; Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.». Варіант «Шаблони діють тільки на віддаленому сервері.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Шаблони визначають невідстежувані файли, які Git не має додавати.; Файл, уже записаний в індексі, не перестає відстежуватися лише через новий шаблон.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про порядок шаблонів .gitignore правильні?',NULL,'["Останній відповідний шаблон визначає результат для шляху.","Шаблон із ! може скасувати попереднє ігнорування доступного шляху.","Перший відповідний шаблон припиняє перевірку всіх наступних.","Порядок шаблонів сортується Git за алфавітом.","Шаблони з ! видаляють файли з диска.","Кожний файл може відповідати лише одному шаблону."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про порядок шаблонів .gitignore правильні? Правило, яке потрібно запам’ятати: Останній відповідний шаблон визначає результат для шляху.; Шаблон із ! може скасувати попереднє ігнорування доступного шляху. Варіант «Останній відповідний шаблон визначає результат для шляху.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Шаблон із ! може скасувати попереднє ігнорування доступного шляху.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Перший відповідний шаблон припиняє перевірку всіх наступних.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Останній відповідний шаблон визначає результат для шляху.; Шаблон із ! може скасувати попереднє ігнорування доступного шляху.». Варіант «Порядок шаблонів сортується Git за алфавітом.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Останній відповідний шаблон визначає результат для шляху.; Шаблон із ! може скасувати попереднє ігнорування доступного шляху.». Варіант «Шаблони з ! видаляють файли з диска.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Останній відповідний шаблон визначає результат для шляху.; Шаблон із ! може скасувати попереднє ігнорування доступного шляху.». Варіант «Кожний файл може відповідати лише одному шаблону.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Останній відповідний шаблон визначає результат для шляху.; Шаблон із ! може скасувати попереднє ігнорування доступного шляху.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два місця підходять для шаблонів, які не потрібно поширювати разом із репозиторієм?',NULL,'[".git/info/exclude для конкретного локального репозиторію","Файл глобальних винятків із core.excludesFile",".gitignore, записаний у спільний коміт","README цільової гілки","Повідомлення локального коміту","Опис pull request"]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два місця підходять для шаблонів, які не потрібно поширювати разом із репозиторієм? Правило, яке потрібно запам’ятати: .git/info/exclude для конкретного локального репозиторію; Файл глобальних винятків із core.excludesFile Варіант «.git/info/exclude для конкретного локального репозиторію» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Файл глобальних винятків із core.excludesFile» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «.gitignore, записаний у спільний коміт» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «.git/info/exclude для конкретного локального репозиторію; Файл глобальних винятків із core.excludesFile». Варіант «README цільової гілки» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «.git/info/exclude для конкретного локального репозиторію; Файл глобальних винятків із core.excludesFile». Варіант «Повідомлення локального коміту» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «.git/info/exclude для конкретного локального репозиторію; Файл глобальних винятків із core.excludesFile». Варіант «Опис pull request» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «.git/info/exclude для конкретного локального репозиторію; Файл глобальних винятків із core.excludesFile».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про шаблон docs/**/*.pdf правильні?',NULL,'["Він може збігатися з PDF у вкладених каталогах docs.","Він обмежує пошук шляхами під каталогом docs.","Він збігається лише з файлом docs.pdf у корені.","Він повторно включає всі PDF через знак !.","Він застосовується лише до відстежуваних PDF.","Він створює каталог docs під час git add."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження про шаблон docs/**/*.pdf правильні? Правило, яке потрібно запам’ятати: Він може збігатися з PDF у вкладених каталогах docs.; Він обмежує пошук шляхами під каталогом docs. Варіант «Він може збігатися з PDF у вкладених каталогах docs.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Він обмежує пошук шляхами під каталогом docs.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Він збігається лише з файлом docs.pdf у корені.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він може збігатися з PDF у вкладених каталогах docs.; Він обмежує пошук шляхами під каталогом docs.». Варіант «Він повторно включає всі PDF через знак !.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він може збігатися з PDF у вкладених каталогах docs.; Він обмежує пошук шляхами під каталогом docs.». Варіант «Він застосовується лише до відстежуваних PDF.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він може збігатися з PDF у вкладених каталогах docs.; Він обмежує пошук шляхами під каталогом docs.». Варіант «Він створює каталог docs під час git add.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Він може збігатися з PDF у вкладених каталогах docs.; Він обмежує пошук шляхами під каталогом docs.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження правильно описують шаблони /temp та temp/?',NULL,'["/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.","temp/ збігається з каталогами temp у межах області дії шаблону.","/temp ігнорує кожний файл із розширенням .temp.","temp/ повторно включає каталог через кінцеву риску.","Обидва шаблони видаляють збіги з індексу.","Обидва шаблони змінюють поточну гілку."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які два твердження правильно описують шаблони /temp та temp/? Правило, яке потрібно запам’ятати: /temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.; temp/ збігається з каталогами temp у межах області дії шаблону. Варіант «/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «temp/ збігається з каталогами temp у межах області дії шаблону.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «/temp ігнорує кожний файл із розширенням .temp.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.; temp/ збігається з каталогами temp у межах області дії шаблону.». Варіант «temp/ повторно включає каталог через кінцеву риску.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.; temp/ збігається з каталогами temp у межах області дії шаблону.». Варіант «Обидва шаблони видаляють збіги з індексу.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.; temp/ збігається з каталогами temp у межах області дії шаблону.». Варіант «Обидва шаблони змінюють поточну гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «/temp прив’язаний до рівня каталогу, де міститься відповідний .gitignore.; temp/ збігається з каталогами temp у межах області дії шаблону.».' FROM topics WHERE slug='gitignore' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Що робить git rebase main у поточній гілці feature?',NULL,'["Переносить коміти feature на вершину main","Об’єднує main у feature лише merge-комітом","Видаляє main","Створює віддалений репозиторій"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що робить git rebase main у поточній гілці feature? Правило, яке потрібно запам’ятати: Переносить коміти feature на вершину main Варіант «Переносить коміти feature на вершину main» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Об’єднує main у feature лише merge-комітом» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Переносить коміти feature на вершину main». Варіант «Видаляє main» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Переносить коміти feature на вершину main». Варіант «Створює віддалений репозиторій» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Переносить коміти feature на вершину main».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Як rebase впливає на ідентифікатори перенесених комітів?',NULL,'["Створює для них нові ідентифікатори","Залишає їх незмінними за іншої бази","Замінює їх назвами гілок","Перетворює їх на URL"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Як rebase впливає на ідентифікатори перенесених комітів? Правило, яке потрібно запам’ятати: Створює для них нові ідентифікатори Варіант «Створює для них нові ідентифікатори» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Залишає їх незмінними за іншої бази» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює для них нові ідентифікатори». Варіант «Замінює їх назвами гілок» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює для них нові ідентифікатори». Варіант «Перетворює їх на URL» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Створює для них нові ідентифікатори».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда продовжує rebase після розв’язання конфлікту та git add?',NULL,'["git rebase --continue","git rebase --abort","git merge --continue","git push --continue"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда продовжує rebase після розв’язання конфлікту та git add? Правило, яке потрібно запам’ятати: git rebase --continue Варіант «git rebase --continue» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git rebase --abort» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue». Варіант «git merge --continue» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue». Варіант «git push --continue» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яка команда скасовує поточний rebase?',NULL,'["git rebase --abort","git rebase --staged","git branch --abort","git fetch --abort"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда скасовує поточний rebase? Правило, яке потрібно запам’ятати: git rebase --abort Варіант «git rebase --abort» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git rebase --staged» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --abort». Варіант «git branch --abort» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --abort». Варіант «git fetch --abort» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --abort».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який параметр відкриває інтерактивний список комітів для rebase?',NULL,'["-i","-v","-u","-d"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Який параметр відкриває інтерактивний список комітів для rebase? Правило, яке потрібно запам’ятати: -i Варіант «-i» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «-v» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «-i». Варіант «-u» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «-i». Варіант «-d» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «-i».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії виконує звичайний rebase поточної гілки на main?',NULL,'["Знаходить коміти поточної гілки після спільної бази.","Повторно застосовує ці зміни поверх актуальної main.","Створює merge-коміт із двома батьками.","Видаляє гілку main.","Відправляє переписану історію до origin."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії виконує звичайний rebase поточної гілки на main? Правило, яке потрібно запам’ятати: Знаходить коміти поточної гілки після спільної бази.; Повторно застосовує ці зміни поверх актуальної main. Варіант «Знаходить коміти поточної гілки після спільної бази.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Повторно застосовує ці зміни поверх актуальної main.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Створює merge-коміт із двома батьками.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Знаходить коміти поточної гілки після спільної бази.; Повторно застосовує ці зміни поверх актуальної main.». Варіант «Видаляє гілку main.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Знаходить коміти поточної гілки після спільної бази.; Повторно застосовує ці зміни поверх актуальної main.». Варіант «Відправляє переписану історію до origin.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Знаходить коміти поточної гілки після спільної бази.; Повторно застосовує ці зміни поверх актуальної main.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві можливості дає інтерактивний rebase?',NULL,'["Змінити порядок вибраних комітів.","Об’єднати кілька комітів через squash або fixup.","Змінити URL віддаленого репозиторію.","Створити pull request на GitHub.","Додати невідстежувані файли без коміту."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві можливості дає інтерактивний rebase? Правило, яке потрібно запам’ятати: Змінити порядок вибраних комітів.; Об’єднати кілька комітів через squash або fixup. Варіант «Змінити порядок вибраних комітів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Об’єднати кілька комітів через squash або fixup.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Змінити URL віддаленого репозиторію.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінити порядок вибраних комітів.; Об’єднати кілька комітів через squash або fixup.». Варіант «Створити pull request на GitHub.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінити порядок вибраних комітів.; Об’єднати кілька комітів через squash або fixup.». Варіант «Додати невідстежувані файли без коміту.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Змінити порядок вибраних комітів.; Об’єднати кілька комітів через squash або fixup.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві дії потрібні для продовження rebase після конфлікту?',NULL,'["Потрібно виправити конфліктний вміст.","Потрібно додати виправлені файли та виконати git rebase --continue.","Потрібно створити новий віддалений репозиторій.","Потрібно видалити цільову гілку.","Потрібно виконати git merge --abort."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві дії потрібні для продовження rebase після конфлікту? Правило, яке потрібно запам’ятати: Потрібно виправити конфліктний вміст.; Потрібно додати виправлені файли та виконати git rebase --continue. Варіант «Потрібно виправити конфліктний вміст.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно додати виправлені файли та виконати git rebase --continue.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Потрібно створити новий віддалений репозиторій.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно виправити конфліктний вміст.; Потрібно додати виправлені файли та виконати git rebase --continue.». Варіант «Потрібно видалити цільову гілку.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно виправити конфліктний вміст.; Потрібно додати виправлені файли та виконати git rebase --continue.». Варіант «Потрібно виконати git merge --abort.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Потрібно виправити конфліктний вміст.; Потрібно додати виправлені файли та виконати git rebase --continue.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві причини вимагають обережності з rebase опублікованої гілки?',NULL,'["Rebase змінює ідентифікатори перенесених комітів.","Інші учасники можуть уже мати попередню версію цієї історії.","Rebase видаляє всі віддалені репозиторії.","Rebase вимикає GitHub Actions.","Rebase робить файли недоступними для читання."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві причини вимагають обережності з rebase опублікованої гілки? Правило, яке потрібно запам’ятати: Rebase змінює ідентифікатори перенесених комітів.; Інші учасники можуть уже мати попередню версію цієї історії. Варіант «Rebase змінює ідентифікатори перенесених комітів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Інші учасники можуть уже мати попередню версію цієї історії.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Rebase видаляє всі віддалені репозиторії.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Rebase змінює ідентифікатори перенесених комітів.; Інші учасники можуть уже мати попередню версію цієї історії.». Варіант «Rebase вимикає GitHub Actions.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Rebase змінює ідентифікатори перенесених комітів.; Інші учасники можуть уже мати попередню версію цієї історії.». Варіант «Rebase робить файли недоступними для читання.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «Rebase змінює ідентифікатори перенесених комітів.; Інші учасники можуть уже мати попередню версію цієї історії.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві команди керують незавершеним rebase?',NULL,'["git rebase --continue продовжує після підготовки виправлень.","git rebase --abort повертає стан до початку rebase.","git branch --continue повторює останній коміт.","git push --abort відновлює робоче дерево.","git clone --continue пропускає конфлікт."]'::jsonb,'[0,1]'::jsonb,'Питання перевіряє: Які дві команди керують незавершеним rebase? Правило, яке потрібно запам’ятати: git rebase --continue продовжує після підготовки виправлень.; git rebase --abort повертає стан до початку rebase. Варіант «git rebase --continue продовжує після підготовки виправлень.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git rebase --abort повертає стан до початку rebase.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git branch --continue повторює останній коміт.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue продовжує після підготовки виправлень.; git rebase --abort повертає стан до початку rebase.». Варіант «git push --abort відновлює робоче дерево.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue продовжує після підготовки виправлень.; git rebase --abort повертає стан до початку rebase.». Варіант «git clone --continue пропускає конфлікт.» неправильний: він суперечить перевірюваному правилу Git. Для цієї умови правильні положення: «git rebase --continue продовжує після підготовки виправлень.; git rebase --abort повертає стан до початку rebase.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Якою стане історія feature після успішного rebase?','# main: A-C
# feature: A-B-D
git switch feature
git rebase main','["A-C-B''-D'', де B'' і D'' мають нові ідентифікатори.","A-B-D-C без зміни ідентифікаторів.","A-C-M, де M є merge-комітом.","A-C, бо коміти feature буде видалено."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Якою стане історія feature після успішного rebase? Правило, яке потрібно запам’ятати: A-C-B''-D'', де B'' і D'' мають нові ідентифікатори. Варіант «A-C-B''-D'', де B'' і D'' мають нові ідентифікатори.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «A-B-D-C без зміни ідентифікаторів.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «A-C-B''-D'', де B'' і D'' мають нові ідентифікатори.». Варіант «A-C-M, де M є merge-комітом.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «A-C-B''-D'', де B'' і D'' мають нові ідентифікатори.». Варіант «A-C, бо коміти feature буде видалено.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «A-C-B''-D'', де B'' і D'' мають нові ідентифікатори.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що потрібно виконати після ручного виправлення app.js?','git rebase main
# Rebase зупинився через конфлікт app.js
# Потрібний вміст app.js уже відновлено вручну','["git add app.js, потім git rebase --continue","git commit --amend, потім git merge main","git restore app.js, потім git push","git branch -d main, потім git rebase"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що потрібно виконати після ручного виправлення app.js? Правило, яке потрібно запам’ятати: git add app.js, потім git rebase --continue Варіант «git add app.js, потім git rebase --continue» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git commit --amend, потім git merge main» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git add app.js, потім git rebase --continue». Варіант «git restore app.js, потім git push» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git add app.js, потім git rebase --continue». Варіант «git branch -d main, потім git rebase» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git add app.js, потім git rebase --continue».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яким буде результат останньої команди?','git switch feature
git rebase main
# Rebase зупинився через конфлікт
git rebase --abort','["Git припинить rebase та спробує повернути гілку до стану перед його початком.","Git пропустить лише поточний конфліктний коміт і продовжить rebase.","Git завершить операцію створенням окремого merge-коміту з main.","Git видалить локальну гілку feature разом із її комітами."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яким буде результат останньої команди? Правило, яке потрібно запам’ятати: Git припинить rebase та спробує повернути гілку до стану перед його початком. Варіант «Git припинить rebase та спробує повернути гілку до стану перед його початком.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «Git пропустить лише поточний конфліктний коміт і продовжить rebase.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git припинить rebase та спробує повернути гілку до стану перед його початком.». Варіант «Git завершить операцію створенням окремого merge-коміту з main.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git припинить rebase та спробує повернути гілку до стану перед його початком.». Варіант «Git видалить локальну гілку feature разом із її комітами.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Git припинить rebase та спробує повернути гілку до стану перед його початком.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Що можна змінити в редакторі, який відкриє команда?','git switch feature
git rebase -i HEAD~3
# У гілці є щонайменше три коміти','["Порядок і спосіб застосування трьох останніх комітів.","URL origin і права доступу GitHub.","Вміст усіх невідстежуваних файлів.","Назву та історію гілки main на сервері."]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Що можна змінити в редакторі, який відкриє команда? Правило, яке потрібно запам’ятати: Порядок і спосіб застосування трьох останніх комітів. Варіант «Порядок і спосіб застосування трьох останніх комітів.» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «URL origin і права доступу GitHub.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Порядок і спосіб застосування трьох останніх комітів.». Варіант «Вміст усіх невідстежуваних файлів.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Порядок і спосіб застосування трьох останніх комітів.». Варіант «Назву та історію гілки main на сервері.» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «Порядок і спосіб застосування трьох останніх комітів.».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Яка команда безпечніше оновить віддалену feature після узгодженого переписування її історії?','git switch feature
git rebase main
# Попередня версія feature вже була опублікована
# Команда узгодила переписування історії','["git push --force-with-lease origin feature","git pull --ff-only origin feature","git fetch --delete origin feature","git remote remove origin"]'::jsonb,'[0]'::jsonb,'Питання перевіряє: Яка команда безпечніше оновить віддалену feature після узгодженого переписування її історії? Правило, яке потрібно запам’ятати: git push --force-with-lease origin feature Варіант «git push --force-with-lease origin feature» правильний: це один із результатів або правил, які безпосередньо виконує умову питання. Варіант «git pull --ff-only origin feature» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git push --force-with-lease origin feature». Варіант «git fetch --delete origin feature» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git push --force-with-lease origin feature». Варіант «git remote remove origin» неправильний: він не відповідає фактичному результату наведеного коду. Правильний результат: «git push --force-with-lease origin feature».' FROM topics WHERE slug='git-rebase' ON CONFLICT (topic_id,difficulty,prompt) DO UPDATE SET code=EXCLUDED.code, options=EXCLUDED.options, correct_options=EXCLUDED.correct_options, explanation=EXCLUDED.explanation, is_active=TRUE;
