UPDATE questions SET template_id='git-git-basics-hard-0', micro_skill='git-basics/distributed', context_key='git-basics/distributed', is_transfer=FALSE, consistency_group_id=NULL, consistency_claims='{}'::jsonb, options='["Локальний репозиторій може містити повну історію.","Розробник може створювати локальні коміти без мережі.","Для кожного коміту потрібне з’єднання з центральним сервером.","Локальна копія містить лише файли робочого дерева.","Індекс зберігається на GitHub.","Гілки можна створювати лише у вебінтерфейсі."]'::jsonb, correct_options='[0,1]'::jsonb, option_ids='["git-git-basics-hard-0:option:0","git-git-basics-hard-0:option:1","git-git-basics-hard-0:option:2","git-git-basics-hard-0:option:3","git-git-basics-hard-0:option:4","git-git-basics-hard-0:option:5"]'::jsonb, correct_option_ids='["git-git-basics-hard-0:option:0","git-git-basics-hard-0:option:1"]'::jsonb WHERE topic_id=(SELECT id FROM topics WHERE slug='git-basics') AND difficulty='hard' AND prompt='Які два твердження відрізняють Git від централізованої системи контролю версій?';
UPDATE questions SET template_id='git-git-basics-hard-1', micro_skill='git-basics/index', context_key='git-basics/index', is_transfer=FALSE, consistency_group_id=NULL, consistency_claims='{}'::jsonb, options='["Індекс визначає вміст наступного коміту.","Індекс містить усю віддалену історію.","Коміт записує підготовлений стан як новий знімок.","Коміт додає до історії всі непідготовлені зміни.","Індекс замінює робоче дерево.","Коміт очищає файли проєкту після запису."]'::jsonb, correct_options='[0,2]'::jsonb, option_ids='["git-git-basics-hard-1:option:0","git-git-basics-hard-1:option:2","git-git-basics-hard-1:option:1","git-git-basics-hard-1:option:3","git-git-basics-hard-1:option:4","git-git-basics-hard-1:option:5"]'::jsonb, correct_option_ids='["git-git-basics-hard-1:option:0","git-git-basics-hard-1:option:1"]'::jsonb WHERE topic_id=(SELECT id FROM topics WHERE slug='git-basics') AND difficulty='hard' AND prompt='Які два твердження правильно описують зв’язок індексу та коміту?';
UPDATE questions SET template_id='git-git-basics-hard-2', micro_skill='git-basics/references', context_key='git-basics/references', is_transfer=FALSE, consistency_group_id=NULL, consistency_claims='{}'::jsonb, options='["Коміт може посилатися на один або кілька батьківських комітів.","Кожний коміт містить URL віддаленого репозиторію.","Гілка зберігає окремий повний набір Git-об’єктів.","Гілка зберігає рухоме посилання на свій кінцевий коміт.","Коміт посилається на файл .gitignore як на свого батька.","Назва гілки входить до вмісту кожного її коміту."]'::jsonb, correct_options='[0,3]'::jsonb, option_ids='["git-git-basics-hard-2:option:0","git-git-basics-hard-2:option:2","git-git-basics-hard-2:option:3","git-git-basics-hard-2:option:1","git-git-basics-hard-2:option:4","git-git-basics-hard-2:option:5"]'::jsonb, correct_option_ids='["git-git-basics-hard-2:option:0","git-git-basics-hard-2:option:1"]'::jsonb WHERE topic_id=(SELECT id FROM topics WHERE slug='git-basics') AND difficulty='hard' AND prompt='Які два твердження правильно описують зв’язок комітів і гілок?';
